/* 2023年6月12日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"r05-20230612-9","dateIso":"2023-06-12","title":"2023年6月12日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5098#one","fetchedAt":"2026-08-14","characters":80359,"voices":[{"i":1,"speaker":"つる委員長","text":"○午後 １時００分開会\nただいまから文教委員会を開会いたします。\n本日は、お手元に配付しております審査・調査予定表のとおり、幹部職員紹介、事務事業概要、報告事項およびその他を予定しております。\nなお、その他におきましては、所管事務調査および行政視察についてのご案内を考えておりますので、よろしくお願いいたします。\n本日も効率的な委員会運営にご協力をよろしくお願いいたします。\n────────────────────────────────────────────\n１ 幹部職員紹介"},{"i":2,"speaker":"つる委員長","text":"それでは、予定表１の幹部職員紹介を議題に供します。\n実質的には、今回が初めての委員会でございますので、改めて委員、理事者の皆様より自己紹介をお願いいたします。\nでは、初めに委員長の私から行います。\n委員長のつる伸一郎です。１年間どうぞよろしくお願いいたします。"},{"i":3,"speaker":"吉田副委員長","text":"副委員長の吉田ゆみこです。よろしくお願いいたします。"},{"i":4,"speaker":"高橋（伸）委員","text":"自民党・無所属の会の高橋伸明でございます。よろしくお願いいたします。"},{"i":5,"speaker":"せお委員","text":"同じくせお麻里です。よろしくお願いいたします。"},{"i":6,"speaker":"安藤委員","text":"日本共産党の安藤たい作です。どうぞよろしくお願いいたします。"},{"i":7,"speaker":"ゆきた委員","text":"公明党のゆきた政春です。よろしくお願いいたします。"},{"i":8,"speaker":"高橋（し）委員","text":"無所属の高橋しんじです。よろしくお願いします。"},{"i":9,"speaker":"石田（し）委員","text":"石田しんごです。よろしくお願いします。"},{"i":10,"speaker":"伊崎教育長","text":"教育長の伊崎でございます。よろしくお願いいたします。"},{"i":11,"speaker":"米田教育次長","text":"教育委員会事務局教育次長の米田でございます。よろしくお願いいたします。"},{"i":12,"speaker":"宮尾庶務課長","text":"庶務課長の宮尾です。どうぞよろしくお願いいたします。"},{"i":13,"speaker":"柏木学務課長","text":"学務課長、柏木でございます。よろしくお願いいたします。"},{"i":14,"speaker":"中谷指導課長","text":"指導課長、中谷です。よろしくお願いいたします。"},{"i":15,"speaker":"丸谷教育総合支援センター長","text":"教育総合支援センター長の丸谷でございます。よろしくお願いいたします。"},{"i":16,"speaker":"唐澤特別支援教育担当課長","text":"特別支援教育担当課長、唐澤です。どうぞよろしくお願いします。"},{"i":17,"speaker":"森学校施設担当課長","text":"学校施設担当課長、森でございます。よろしくお願いいたします。"},{"i":18,"speaker":"吉田品川図書館長","text":"品川図書館長、吉田でございます。よろしくお願いいたします。"},{"i":19,"speaker":"柏原子ども未来部長","text":"子ども未来部長の柏原でございます。どうぞよろしくお願いいたします。"},{"i":20,"speaker":"大澤子ども育成課長","text":"子ども育成課長の大澤でございます。よろしくお願いいたします。"},{"i":21,"speaker":"染谷子ども家庭支援センター長","text":"子ども家庭支援センター長の染谷と申します。よろしくお願いいたします。"},{"i":22,"speaker":"長谷川児童相談所開設準備課長","text":"児童相談所開設準備課長の長谷川と申します。よろしくお願いいたします。"},{"i":23,"speaker":"飛田子育て応援課長","text":"子育て応援課長の飛田と申します。よろしくお願いいたします。"},{"i":24,"speaker":"立木保育課長","text":"保育課長の立木です。どうぞよろしくお願いいたします。"},{"i":25,"speaker":"今井保育教育運営担当課長","text":"保育教育運営担当課長の今井です。どうぞよろしくお願いいたします。"},{"i":26,"speaker":"石井保育支援課長","text":"保育支援課長の石井と申します。どうぞよろしくお願いいたします。"},{"i":27,"speaker":"つる委員長","text":"それぞれありがとうございました。\nなお、事務局からは、深井書記と新倉書記が当委員会の事務に当たりますので、よろしくお願いをいたします。\nこのメンバーで１年間、実りある委員会にしてまいりたいと思いますので、改めてよろしくお願いいたします。\n以上で本件を終了いたします。\n────────────────────────────────────────────\n２ 事務事業概要\n(1) 教育委員会"},{"i":28,"speaker":"つる委員長","text":"次に、予定表の２、事務事業概要を議題に供します。\n進め方でございますけれども、まず、(1)の教育委員会につきまして一括してご説明いただいた上で、一括して質疑を行い、その後、(2)の子ども未来部につきまして、同様に一括してご説明をいただき、一括して質疑を行うという進行になります。\nなお、事務事業概要につきましては、例年に倣い、新しい委員で構成される最初の委員会で、各所管の事務について概要説明を受けるものであります。\nしたがいまして、具体的な質疑につきましては、今後の報告事項等の案件の中で行っていただきたいと思いますので、本日は説明・質疑とも、くれぐれも簡潔にお願いいたします。\nそれでは、教育委員会から、一括してご説明願います。"},{"i":29,"speaker":"米田教育次長","text":"それでは、教育委員会事務局の令和５年度の事務事業概要についてご説明を申し上げます。\n緑色の表紙の事務事業概要でございます。こちらを２枚ほどおめくりいただきまして、下にページを振っておりますので、まず、１ページからご説明をいたします。\n１ページにつきましては、品川区教育委員会の教育目標を記載してございます。\n１枚おめくりいただきまして、２ページから４ページまでが基本方針となります。黒ゴシックで書いてある５項目が、先ほどの教育目標を捉えたもので、より具体的な方針を定めて、品川区教育委員会が教育施策を総合的に実施する、このような位置づけになっております。\n次の５ページ、Ｉ、教育委員会とございます。\n教育委員会の概要として、地方教育行政法に基づきまして、合議制の執行機関として教育委員会が置かれております。委員の５名の氏名、任期は表のとおりでございます。\nおめくりいただきまして、６ページ、教育委員会事務局の組織でございます。５つの課に担当課長を設置しておりまして、係の名称、人数等を記載してございます。\n７ページに、II、品川教育ルネサンスとございます。項目の２、目指す教育といたしましては、四角囲みにございますとおり、１番目、品川コミュニティ・スクールの実施による、地域とともにある学校づくり、２番目、小学校・中学校・義務教育学校の三校種体制による学校教育の推進、３番目、義務教育９年間の一貫したカリキュラムの実現、これらを柱として、教育を推進しているものでございます。\n以降、各課の事務事業につきましては、各担当課長よりご説明申し上げます。"},{"i":30,"speaker":"宮尾庶務課長","text":"それでは、続きまして、私から庶務課の事務事業概要についてご説明をいたします。\n９ページをご覧ください。\nまず、事務分掌でございます。庶務課は大きく４つの係組織で構成をしております。所掌する事務といたしましては、教育委員会事務局全体の総括的な事業といたしまして、教育委員会の開催、予算決算の総括、行政財産管理の総括、学校勤務職員の人事の一部を担当するほか、ＰＴＡ関連事業、学校施設の改築、維持管理、修繕、そして、文化財の保存、活用などを所掌してございます。\nおめくりいただきまして、１０ページをご覧ください。事務事業でございます。\nまず、庶務係でございますが、教育予算、教育委員会、教育広報、統計調査などの事務局の総括的な業務を行ってございます。\n１１ページに参ります。学校勤務職員についての人事、研修、健康管理等に関する事務を行っております。\n下のほうに参りまして、ＰＴＡ関連事業でございます。少年少女スポーツの普及をはじめ、おめくりいただきまして、１２ページ、丸の１番目、家庭教育講演会の開催、２番目、家庭教育学級等の委託、３番目、家庭教育力の向上支援を行っております。そのほか、８３運動の推進、１３ページに参りまして、学校に勤務する職員への被服貸与、児童通学安全確認業務の委託、学校受付業務・用務業務の委託等を実施してございます。\n丸の４番目でございますが、今年度から、学校で発生する様々なトラブルへの対応といたしまして、教育委員会事務局の各課が、専門家へ随時相談可能な体制を構築しております。\n続きまして、学校施設計画係、おめくりいただいて、１４ページ、１５ページの学校施設整備担当の事務事業概要につきましては、この後、学校施設担当課長よりご説明を申し上げます。\nおめくりいただきまして、１６ページをご覧ください。文化財係でございます。\n１番目のひし形、文化財保護審議会ですが、こちらは１０名の委員で構成をしており、年３回程度開催をしております。\n２番目のひし形、文化財の保存と活用でございます。丸の１番目、４月１日現在の指定件数は１４３件でございます。最近指定・登録された文化財が２件ございます。こちらは後ほどご報告をさせていただきます。\nそのほか、１７ページに参りまして、文化財めぐり、一般公開などの普及啓発事業を実施しております。"},{"i":31,"speaker":"森学校施設担当課長","text":"では、資料の１３ページにお戻りいただきまして、中ほどの学校施設計画係でございます。学校施設計画係では、学校改築の計画や調整を行っております。現在小学校６校、中学校１校の改築を進めております。\n浜川小学校では、令和６年３月に校舎棟が完成する予定であり、令和７年度には外構を含め全ての工事が完了する予定です。\nその下、第四日野小学校では、令和５年７月に校舎棟が、令和７年度に体育館棟がそれぞれ完成する予定です。令和８年度には外構工事を含め全ての工事が完了する予定です。\n浜川中学校では、令和５年１１月に体育館棟が、令和８年度に校舎棟が、それぞれ完成する予定です。令和９年度には、外構工事を含め全ての工事が完成する予定です。\n城南第二小学校では、令和５年８月頃より改築工事に着手し、令和７年度に校舎棟が、令和９年度に体育館棟が、それぞれ完成する予定です。令和１０年度には、外構工事を含め全ての工事が完成する予定です。\n源氏前小学校では、今年度実施設計を行い、令和６年度の改築工事着手を目指します。また、令和５年１１月頃より既存プールを解体いたします。\n鈴ケ森小学校では、今後、設計委託業者と契約いたしまして、基本設計を進める予定です。\n最後に、浅間台小学校ですが、今年度、改築工事の準備として敷地測量を行う予定です。\n続きまして、１４ページをお開きください。学校施設整備担当では、学校の改築や維持管理、修繕を担当しております。今年度予定する学校施設整備については、記載のとおり工事を予定しております。主なもので、校舎等整備では、便所改修から自動火災報知設備改修まで、記載の学校にて工事を予定しております。\n中段、外壁、屋上防水は、記載の小学校４校、中学校１校で工事を予定しております。\n下段でございますが、学校体育施整備費です。次ページの記載のとおり工事等を予定しております。主なもので、プール整備から塀改修まで、記載の学校にて工事を予定しております。"},{"i":32,"speaker":"柏木学務課長","text":"それでは、私からは、学務課の事務事業について説明をいたします。\n１８ページをご覧ください。\n学務課は、学校選択制を始めとする就学事務、効率的・効果的な学校運営実現のため、学校備品の購入など、教育環境の整備、校務・教育事務の効率化や、ＩＣＴ機器を活用した教育活動のための環境整備、健康診断、学校給食等の実施、宿泊行事をはじめとした校外活動等の事務を所管しております。また、今年度につきましては、学事制度審議会を設置し、就学人口の増加等に対応した教育環境の確保等について審議を行うこととしております。\n今年度は、学務課は、記載の２係２担当の体制でそれぞれの事務を実施してまいります。\n１９ページをご覧ください。\n中段、学事係です。初めに学校選択制の実施でございます。小学校・義務教育学校（前期課程）の学校選択については隣り合った通学区域の学校から、中学校・義務教育学校（後期課程）は区内全域から希望申請をすることができる制度として運用をしております。\n２０ページ、中ほどに希望申請の内容を記載してございます。\n学校ごとの状況につきましては、２１ページのほうに記載をしております。\n２２ページ、学級編制でございます。\n学級編制は、令和３年度から、基本は３５人学級となりましたが、令和５年度については、経過措置で１年生から４年生が３５人編制となっております。また、７年生については、東京都の教員加配措置により、３５人学級で対応をしております。中ほどにあります表は、小学校、中学校全体の学級編制を掲載しております。各学校の状況につきましては、５７ページ、５８ページのほうに記載をしております。\nおめくりいただきまして、２３ページ、就学援助でございます。\n就学援助につきましては、経済的に就学が困難と認められる児童・生徒の保護者に対し、学用品等の援助を行っているものです。受給状況については、２３ページから２４ページの表のとおりでございます。\n２４ページ、学事制度担当でございます。\n今年度、学事制度審議会の設置に伴い、その事務を担当するため、新たに組織したものとなります。\n続きまして、校務情報管理対策担当でございます。こちらの担当は、学校の情報管理安全対策、学校事務や、校務、教材系のシステムの運用管理、児童・生徒用タブレット端末の運用管理等、学校のＩＣＴ全般を担当しております。\n２５ページ、保健給食係でございます。保健給食係は、児童・生徒の健康、衛生管理を担当しております。\n２６ページ、学校給食でございます。今年度から、区立学校の給食費無償化を実施しております。\nおめくりいただきまして、２７ページ、下段になりますが、校外施設でございます。昨年度は新型コロナウイルス感染症の感染拡大のため実施できなかった学年の繰越し実施を行いましたが、今年度は、例年どおりの学年で実施をしております。\n最後に２８ページ、中段ですが、多子家庭給食費補助でございます。こちらは、区立学校の給食費無償化に伴い今年度から廃止となりました。\n簡単ではございますが、学務課の事務事業は以上となります。"},{"i":33,"speaker":"中谷指導課長","text":"続きまして、指導課に係る事務事業についてご説明をいたします。\n２９ページをご覧ください。\n指導課では、教職員の人事・服務・給与・研修等に関すること、一貫教育や品川コミュニティ・スクールなど、教育施策の企画に関することを担っております。\n事務分掌は、教職員人事係、指導主事、学校地域連携係の３つのラインで進めてまいります。\nまず、３０ページをご覧ください。\n教職員人事係は、人事・服務・働き方改革等、人事関係の業務を中心に行っております。一番下の区固有教員の採用につきましては、現在、選考の応募受付を行っております。こちらにつきましては、後ほど報告をさせていただきます。\n次に、３１ページ以降に掲載しておりますように、教育管理職の選考手続、代替教職員、非常勤講師の任免、服務関係、教育実習に関する事務、教職員の給与・旅費に関する事務を行います。\n３２ページをご覧ください。\n上段に記載しております、学校働き方改革についてですが、全区立学校・幼稚園へのスクール・サポート・スタッフ等の配置や、教員の勤務時間外の電話委託などに加えまして、副校長補佐の任用を開始いたしました。今年度は、経験の浅い副校長配置校や、副校長の長時間勤務が常態化している学校を中心に配置をしてまいります。\n今後も、より一層、しながわ働き方ルネサンスを進めてまいります。\n３３ページ以降につきましては、指導主事および学校地域連携係の事務事業でございます。一貫教育の推進につきましては、品川区立学校教育要領に基づき進めるとともに、指導方法や教材等の充実に向けて検討する委員会や、小中一貫教育全国連絡協議会の運営を行います。今年度は、全国連絡協議会の事務局として、全国サミットを代替するイベントを実施する予定です。品川区の教育に関する評価やリーフレット等の発行などの事業も展開してまいります。また、習熟度別学習の充実、学力定着度調査、特色ある教育活動経費、学力向上プラン等の品川区独自の施策につきましても、引き続き実施してまいります。\n３４ページをご覧ください。中段に掲載いたしました、品川コミュニティ・スクールにつきましては、各学校で校区教育協働委員会と学校支援地域本部を設置いたしまして、教育活動の充実に向けて様々な学校支援活動を行っております。今年度は、校区教育協働委員会に学校の児童・生徒も参加する機会を設定いたします。「よりよい学校にしていくためには」という趣旨のテーマの下、子どもの意見を聞きながら、熟議を通して課題解決を深めるとともに、今後の地域とともに歩む学校づくりを一層推進していく機会とするため、コミュニティ・スクールデイを開催いたします。\n３５ページに参りまして、品川英語力向上推進プランにつきましては、１年生から６年生に引き続きＡＬＴやＪＴＥの活用、４年生を対象としたジュニア・イングリッシュキャンプですが、今年度も自校での開催に加えまして、東京都が開設したTOKYO GLOBAL GATEWAY BLUE OCEANの活用も行ってまいります。\n７年生から９年生はＡＬＴの派遣、グローバル人材育成塾やイングリッシュキャンプの開催、品川オンラインレッスンにつきましては、対象を８年生、９年生に実施いたします。\n３６ページをご覧ください。学校２０２０レガシー事業でございます。これまで推進してきたオリンピック・パラリンピック教育を、競技大会後も長く続く教育活動として継続・発展をさせ、共生・共助社会の形成を担う子どもたちの育成をしてまいります。\n昨年度は、各学校と教育委員会の取組にスポーツ庁から評価をいただき、Sport in Lifeアワード２０２２自治体部門で優秀賞を受賞することができました。今後も、２０２４夏季パリオリンピックが開催予定であることも見据えながら、現在行っておりますブラインドサッカーの競技体験教室を引き続き行うとともに、各校で行っているオリンピック・パラリンピック教育の活動をより充実できるようサポートしてまいります。"},{"i":34,"speaker":"丸谷教育総合支援センター長","text":"それでは、教育総合支援センターの事務事業について説明をいたします。３７ページをご覧ください。\n教育総合支援センターの主な機能は、（１）から（５）に記載のとおりでございまして、教育課程の管理、いじめ・不登校対応、特別支援教育、教育相談等を所掌しております。\n事務分掌についてでございます。教育事務係、相談支援担当、指導主事、次のページに参りまして、今年度から特別支援教育担当を設けております。今年度から組織改正により、特別支援教育係から、担当として担当課長を配置しております。\n続いて他課との連携事業についてですが、特別支援教育、健全育成、体力向上、人権・同和教育、ＩＣＴ教育については、他部局との連携をしながら実施しております。\n各係担当の事務事業概要についてです。教育事務係につきましては、教育総合支援センターの管理・運営、３９ページに参りまして、教育資料展示室、こちらは教科書センターでございます。市民科・各教科の事務、学校における教育活動への支援を行っております。\n相談支援担当は、相談機能の一元化、教育相談室の運営、４０ページに参りまして、いじめ対策。いじめ対策のＨＥＡＲＴＳにつきましては、令和５年度はさらに２名増員し、指導主事６名、教育アドバイザー１名、スクールソーシャルワーカー６名、教育心理相談員５名、学校生活指導専門員（警察ＯＢ）１名の１９名で編成しております。\n４１ページに参りまして、不登校等の対応、部活動指導員の配置を行っております。部活動指導員の配置は、令和５年度につきましては、中学校・義務教育学校全１５校に対して２名ずつの配置を目標としてございます。\n続いて指導主事でございます。体力向上施策の推進、４２ページに参りまして、市民科の推進、人権・同和教育の推進、教員研修・校内研究の推進、４３ページに参りまして、土曜授業の実施、そして、その他の事業として、連合行事、安全・防災、学校の特色ある教育活動や教育課題への支援を行っております。\n特別支援教育担当につきましては、担当課長より説明をいたします。"},{"i":35,"speaker":"唐澤特別支援教育担当課長","text":"私からは、特別支援教育担当課の事務事業についてご説明申し上げます。\n担当課では、一人一人の教育的ニーズを把握し、その持てる力を高め、生活や学習上の困難を改善または克服するため、適切な指導および必要な支援を行うために、校内体制の整備、充実に向けた取組、特別支援学級、特別支援教室の整備・充実を図っております。\n資料４４ページ、４５ページをご覧ください。１番目のひし形の四角、就学相談・転学相談の実施につきましては、今年度は５月３０日から受付を始めておりまして、今年度より、これまでの電話や来所での受付に加え、ウェブでの受付を実施しているところでございます。\n２番目、３番目のひし形につきましては、児童・生徒の実態に応じまして、必要な人材を支援しているところでございます。\n４５ページに移りまして、巡回相談員の配置につきましては、小学校・中学校・義務教育学校の５、６校を一つのグループとして、１名の巡回相談員が訪問しております。今年度より、巡回相談員を束ねる教育総合支援センターに配置されているチーフを３名から４名に増員しております。\n続いて、発達障害教育支援員の配置につきましては、昨年度からモデル実施しておりますが、今年度は昨年度の５校から、さらに対象学校を拡充し、合わせて１５校で実施しております。\n特別支援教室及び清水台小学校の病弱特別支援学級「さいかち学級」につきましては、昨年度同様に今年度も同じ規模で実施しております。"},{"i":36,"speaker":"吉田品川図書館長","text":"それでは、私から、品川区立図書館の事務事業の説明を行います。\n４６ページをご覧ください。区立図書館では、１１の図書館と図書取次施設２か所、行政サービスコーナー２か所にて図書事業を行っております。品川図書館を除く地区図書館１０館につきましては、指定管理者制度を導入しております。\n事務分掌については、庶務を行う管理係、各種事業を担当する事業担当を置いております。\n他課との連携事業につきましては、４６ページ、４７ページのうち、主なものとしては、子ども読書活動の推進として、児童センター、学校、保育園、保健センターと連携するとともに、認知症カフェでは高齢者地域支援課と連携し、この６月より図書館では５館目となる認知症カフェを大崎図書館分館でも実施いたします。\n４８ページをご覧ください。事務事業の全館共通のサービスです。開館時間等に変更はございません。区内の図書館は、大みそかから三が日以外、いずれかの図書館を開け、利便性を確保しております。サービスの内容は記載のとおりです。\n５１ページ、品川図書館が中央館として実施するサービスです。中ほど、電子図書館、音楽データベースなど、図書館に来館しなくても利用できるサービスも提供しております。\n５２ページ、新規事業、上から２番目、デジタルアーカイブによる資料の提供は、品川区史など区の歴史を紹介する資料をデジタル化し、今年３月よりインターネットで公開しました。令和５年度も資料の充実を図ってまいります。\n品川図書館１００周年記念事業については、１００年の歩みをまとめた冊子の作成とともに、館内におけるパネル展等を予定しております。\nそれから、申し訳ございません、資料に訂正がございます。５４ページの、利用状況集計の最も下段になります。ちょっと字が小さいところでございます。レファレンス等件数でございますけれども、右から６列目の八潮図書館、２０７件については２,１２９件の誤りとなります。そのため、最も右の合計欄の６万４,３１３件は６万６,２３５件となります。大変失礼いたしました。"},{"i":37,"speaker":"つる委員長","text":"説明が終わりました。\nこれより質疑を行います。\n本件について、ご質疑等がございましたら、ご発言願います。"},{"i":38,"speaker":"安藤委員","text":"学校教育事業全般に関わることとして、ちょっと今、教員不足が深刻になっていると思うのですけど、ちょっとその点１点お伺いしたいのですが、都内でいうと今年４月時点で教員の欠員数が計約８０人でしたという報道ありましたけど、品川の場合、新年度になって学級担任が埋まらないで、専科教員ですとか、非常勤や副校長などで対応している事例というのは、何で、何クラスあるのかないのか伺いたいというのが１つです。\nもう一つは、この教育目標などの点なのですけど、教育目標と基本方針の中に、品川教育ルネサンスという言葉は出てこないのですが、冒頭のこの目標、方針と、この７ページにある教育ルネサンスという、この関係、どんな関係性にあるのかというのをちょっと伺いたいと思います。"},{"i":39,"speaker":"中谷指導課長","text":"教員不足の件にお答えさせていただきます。今回、年度初めに、４月７日に学級編制で改めて、クラスの決定というところを区として行うのですけれども、その時点で、数件、学級の増ということによって、先生が必要だという対応をした案件があったのですけれども、その辺りにつきましては速やかに対応をさせていただいております。\n先ほどご指摘のありました、副校長先生が学級担任に入るということもありました。ただ、ずっとその状況を続けていることではございませんで、替わりの先生が見つかり次第、バトンタッチという形で変更して、本来である学級担任の先生がその業務を行い、副校長先生が副校長業務を行うというような形になっております。"},{"i":40,"speaker":"米田教育次長","text":"教育目標はその名のとおり、品川区教育委員会としての教育の目標でございます。対しまして、品川教育ルネサンスにつきましては、特に教育委員会全体の中での学校教育の方向性について主にまとめたもので、これまでの変遷も含めて記述しているものでございます。"},{"i":41,"speaker":"安藤委員","text":"では、教員のほうですけど、今の時点で学級担任が埋まっていないという事態はないと。その担任本来が当たるべき正規職員の方ではなく、専科ですとか非常勤とか副校長等で対応している事例は今はないということでよろしいのかという確認をさせてください。それと、ぜひそういったことがありましたら、速やかに全力を挙げて対応していただきたいという、これは要望です。\nあと、教育目標のところですが、分かりました。\n７ページの、これまでの教育の歩みが書いているのですけど、この歩みというところです。第一段落のほうなのですが、ちょっとこの記述についてお伺いしたいのです。これ、プラン２１の具体的、こういうふうに取り組んできましたという中身として選択制、学力テスト、外部評価、小中一貫教育が挙げられているのですが、最後に顕著な成果を上げたと総括されていますけど、ちょっとここを見ると、地域や保護者との関係の中で成果を述べられているのですが、重要なのは子どもにとってどうなのかということだと私は思うのですが、その記述がないので、これだけ聞きたいのです。プラン２１が子どもにとって顕著な成果を上げたというふうには、あまり教育委員会としては認識していないということなのでしょうか、伺いたいと思います。"},{"i":42,"speaker":"中谷指導課長","text":"先ほどの教員不足のご指摘の件ですけれども、お話しいただいたとおりでして、今現在、非常勤の方ですとか、副校長ですとか、専科の方で対応するというようなことはございませんで、しっかりやっております。また、そのようなことが年度を通じまして起きたときには、速やかに対応するということでやってまいりたいと思っております。"},{"i":43,"speaker":"米田教育次長","text":"７ページのIIの１のところですが、特に記述は前年度と変えているものではございませんけれども、品川区の教育が、いわゆる、まず教職員の意識改革というところから始めての教育改革を行ってきたというところを前段に書かせていただきまして、その中で当然子どもに対するよい影響もあったというような形で認識しているものでございますが、記述は具体的にあるかというと、ないかもしれません。"},{"i":44,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":45,"speaker":"高橋（し）委員","text":"幾つかお尋ねします。\n２４ページの学事制度審議会、今年度ということですが、そのスケジュール的なところが分かれば簡単に教えてください。もう諮問されているとしたら、その辺です。\nもう一つは、人数のところなので５９ページで、区費で管理職の先生がいらっしゃると思うのですが、どちらの小学校に行かれているかということと、あと副校長の補佐の方が配置されている、校長先生のフォローということで大変よい仕組みだと思います。それはどちらの小学校あるいは中学校でしょうか。教えてください。\nそれからあともう一つは、ページが分からないのですけど、共同の部活動について力を入れていくということなのですが、今年度、どんな感じで進めていくのかを簡単で結構ですからお願いします。"},{"i":46,"speaker":"柏木学務課長","text":"それでは、私のほうから学事制度に関わるスケジュールの話ですが、学事制度ですが、来月７月に第１回を開催するということで現在準備を進めているところでございます。ですので、諮問文等についても現在検討しているところでございます。"},{"i":47,"speaker":"中谷指導課長","text":"まず、区の固有の教員の管理職ですけれども、３人になりまして、小学校につきましては、大井第一小学校、台場小学校、そして浜川小学校です。全員、３人とも小学校への配置ということになっております。\nそれから、副校長補佐につきましては、昨年、２つの学校にトライアルの形で配置をしておりましたが、今回は、小中義務教育学校合わせて合計２２校に配置をさせていただいております。\nそして、部活動の状況ということですけれども、こちらは来月の文教委員会のほうでご報告をさせていただきたいというふうに考えております。"},{"i":48,"speaker":"高橋（し）委員","text":"それぞれ、区としてよい仕組みに進めていると思いますので、ぜひ進めていっていただければと思います。"},{"i":49,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、教育委員会の事務事業概要につきましてはこれで終了いたします。\n────────────────────────────────────────────\n(2) 子ども未来部"},{"i":50,"speaker":"つる委員長","text":"続きまして、子ども未来部の事務事業概要について、一括してご説明願います。"},{"i":51,"speaker":"柏原子ども未来部長","text":"それでは、私のほうから、子ども未来部の事務事業の概要についてご説明いたします。\n白い表紙の子ども未来部の事務事業概要をご覧ください。\nまず、表紙をおめくりいただきまして、１ページ、ここから目次になってございまして、１ページから４ページまでが目次でございます。\n５ページにお進みいただきまして、組織と分掌事務で、まず、（１）として子ども未来部の組織図が出てございます。子ども未来部といたしましては、５課１センターというところで構成されてございまして、上から３番目の児童相談所開設準備課、こちらのほうが、令和６年１０月に区立児童相談所開設に向けて、今年度より課として独立をいたしました。\nおめくりいただきまして、６ページ、職員配置状況でございまして、各課ごとの職種ごとに分けた職員の配置状況を載せさせていただいてございます。正規職員全員で９６７名というところでございます。\nその下、下段からは子ども未来部の分掌事務ということで、各課ごとの分掌事務でございます。これは後ほど担当課のほうからも、併せて説明をさせていただきます。\n８ページにお進みいただきまして、参考ということで、子ども未来部の令和５年度予算内訳で、各課ごとの今年度の予算を載せさせていただいてございます。民生費と書いてあるところが、これが歳出予算になりますけれども、合計で４３７億９,７６７万４,０００円でございまして、区全体の予算に対しまして２２％となってございます。\n続きまして、９ページでございます。子どもに関する施策の現状と考え方でございまして、子ども未来部の施策に対する考え方でございます。これは上段、記載のとおりでございますけれども、子どもを取り巻く課題につきましては、ひきこもりであったり、不登校、児童虐待、ＳＮＳの普及による影響、また、いじめなどと、ますます複雑化してきているといったところでございます。また、人口減少下における保育需要への対応や、特別保育の充実など、多様な支援が求められているといったところもございます。\nまた、ここに記載はございませんけれども、国のほうでもこの令和５年４月からこども家庭庁が設立されまして、国のほうも、次元の異なる少子化対策で、施策を大きく打ち出してきているといったところで、大きな転換期に入ってきているというふうに捉えているところでございます。\n子育ての第一義的な責任は親にあるといったところを前提にしながらも、子どもの健やかな育ちを地域社会全体で支えていくといったことがますます重要と捉えているものでございます。\nこうしたことから子ども未来部といたしましては、子どもの健やかな成長を支援する、「子育て３つの無償化（第２子保育料、学校給食、高校生等の医療費）」などをはじめ、「子育て・教育で選ばれるしながわ」に向け、子育て家庭を全力で支援していきたいというふうに考えているものでございます。\nそれ以降につきましては、各課ごとの説明の中で、併せてご説明させていただきます。"},{"i":52,"speaker":"大澤子ども育成課長","text":"私から、子ども育成課の事業についてご説明いたします。\n１５ページをご覧ください。（１）次世代育成支援では、子育てガイドの発行、パパママ応援アプリの活用などにより、情報発信を行っております。（２）からは、青少年等の健全育成に関わる事業となります。青少年問題協議会の運営、ページおめくりいただきまして、（３）「明るい家庭づくり」の啓発、（４）ジュニア・リーダー教室では、令和４年度からキャンプ等の活動を再開しております。\n１７ページ、青少年委員活動、同じく青少年育成者研修、１８ページ、青少年育成事業につきましては、コロナ禍で活動を控えておりましたが、元に戻りつつあります。\n１９ページ、体験型育成事業として、宮古市との親子交流事業を行っております。\n２０ページ、子育て応援プログラム事業でございます。（１）子育て交流サロンは、０～２歳児親子の交流と相談の場となっております。\n２１ページ、（２）子育て講座は、離乳食や、また、２３ページにございますように、アレルギーに関する講座等を実施しております。\n２４ページ、在宅子育て支援事業です。（１）すくすく赤ちゃん訪問事業、（２）親育ち支援事業、ページをおめくりいただきまして、自主グループ支援など、育児不安の解消を目的に、様々な形で事業を展開しております。\n２７ページ、こども冒険ひろばは、北浜公園としながわ区民公園のほか、荏原地区においても同様の事業を行っておりますが、７月より、荏原中央公園の改修工事に伴い、小山２丁目のあさひ公園に実施場所を移動いたします。\n２８ページ、子育てメッセや、子育て支援グループの活動支援など、地域活動の支援にも力を入れているところです。\n３０ページ、児童センター事業です。それぞれの事業の実績欄をご覧いただきますと、コロナ禍により休止していた事業が多くございますが、令和４年度より徐々に再開しております。\n３５ページに、児童センター２５館の一覧がございます。現在、一本橋児童センターは改築中のため休館しております。また、中原児童センターは、工事のため、７月に旧第一日野小学校跡地に仮移転となります。\n３７ページ、すまいるスクール事業です。平成１３年度のモデル実施から、時代のニーズに合わせ、事業形態を変えながら、学校と連携し、運営に当たっております。\n次に、４１ページ、子ども・若者育成支援事業です。（１）品川区子ども・若者計画は、令和５年度から第２期の計画に入ったところです。（２）のフリースペース、ページおめくりいただきまして、エールしながわにおきましては、生きづらさを感じる子どもや若者、また、その家族を対象に相談や支援を行っております。"},{"i":53,"speaker":"染谷子ども家庭支援センター長","text":"続きまして、私からは子ども家庭支援センターの事務事業についてご説明をいたします。４４ページをご覧ください。\nまず、１の子どもに関する相談事業でございます。１行目にありますように、１８歳未満の児童に関する相談および児童虐待通告については区が一義的な窓口となっておりまして、子ども家庭支援センターが児童相談所等の関係機関と連携しながら、要保護児童等の相談支援を行っております。\n次の４５ページの3)児童家庭相談の実施状況に相談実績を記載しております。件数はこちらご覧のとおり年々増加しておりまして、令和４年度におきましても、児童虐待相談をはじめ相談件数は伸びている状況でございます。\nその下の（２）品川区要保護児童対策地域協議会は、子ども家庭支援センターが調整機関となりまして、子どもに関わる地域の各関係機関と連携して、要保護児童等への支援を行っております。\n次のページをおめくりいただきまして、ここからは、協議会の構成等を記載しておりまして、第１層の全体会から、ページの下段、第２層の地域分科会、それから４７ページの上段にまいりまして、第３層の協議会ケース会議について、開催実績等につきましては記載のとおりでございます。\n４７ページ下段、（３）品川区における「居住実態が把握できない児童」の把握および関係機関連携につきましては、令和４年度の報告件数は０件、各調査を通じまして、対象の全ての児童について把握ができているところでございます。\n続きまして、４８ページ、（４）児童虐待防止推進等に関する取組につきましては、今年度も引き続き実施をしてまいります。\n４９ページに参りまして、２の在宅子育て支援事業につきましては、（１）家庭あんしんセンターにおきまして、子育て相談のほか、3)の記載の部分になりますけれども、ショートステイ、トワイライトステイといった事業などを実施しておりまして、新型コロナウイルスの行動制限の緩和などの影響によりまして令和４年度には大きく実績の件数が伸びているところでございます。\n５０ページに参りまして、（２）要支援ショートステイにつきましては、記載のとおりの実績でございますが、次の（３）の乳幼児ショートステイ事業につきまして、こちらは令和４年度からの新規事業でございますが、非常に多くのご予約、お問合せをいただいておりまして、令和５年度から定員を１名増やしまして、実施をしているところでございます。\n次に、５２ページまでページをおめくりいただきまして、３番、しながわネウボラネットワークでございます。子ども家庭支援センターにおきましては、（１）産後の家事育児支援としてヘルパー等の利用助成を行っております。実績は大きく伸びているところでございますけれども、令和５年度はさらに、これまで母親のみを助成の対象としていたものを、父親を含む、お子さんを養育しているご家庭を助成対象に拡充し、実施をしてまいります。\n５３ページに参りまして、（３）しながわネウボラネットワーク連携強化事業では、法改正により設置が求められております、こども家庭センターの議論を含め、母子保健分野との連携強化を図るため、記載の取組を進めてまいります。\n最後に、５４ページ、４、ヤングケアラー支援事業でございます。令和４年度は、教職員や関係機関向けのアンケート調査を実施いたしました。その結果を踏まえ、令和５年度は、より幅広く支援等を展開してまいります。\nこちら、1)の行の最後に記載しております、お子さん本人に向けたアンケート調査や、2)の中ほど、こちら既に子ども家庭支援センターで相談を開始しておりますけれども、ヤングケアラーコーディネーターの配置等を通じまして、様々な支援の取組を進めてまいりたいと考えております。"},{"i":54,"speaker":"長谷川児童相談所開設準備課長","text":"それでは、私から児童相談所移管推進事業についてご説明申し上げます。\n５５ページをご覧ください。区は、児童相談行政の中核となる児童相談所の設置を目指し、施設整備や人材の確保・育成等の諸課題に取り組み、広域的な課題に対しては、都、特別区並びに関係部署・関係機関と連携しつつ、令和６年１０月の開設に向けた準備を着実に進めてまいります。\n（１）としまして、運営体制等の整備につきましては、運営マニュアルや業務委託の検討のほか、児童相談システムや電話応対支援システムの新規開発に着手してまいります。\n（２）の人材の確保・育成につきましては、庁内研修により機運醸成を図るほか、先行開設区での職員派遣や専門研修を受講することで、専門性の向上を図ってまいります。\n（３）の計画確認作業および国への政令指定要請につきましては、児童相談所設置市として国から政令指定を受けるために必要な手続となりますので、令和４年３月に策定した計画書に基づきまして着実に進めてまいります。\n（４）の建物活用および維持管理につきましては、令和５年１月に建物が完成しましたので、本年４月１日より執務室を移転し、準備業務を進めております。"},{"i":55,"speaker":"飛田子育て応援課長","text":"それでは、子育て応援課の事務事業概要について説明させていただきます。\n５６ページをご覧ください。１、児童の各種手当でございます。児童手当をはじめ、こちらのほうは様々な手当の支給を行っております。\n６２ページをご覧ください。２、子どもすこやか医療費助成事業です。昨年度までは中学生までが医療費の対象でしたが、今年度より新たに高校生等までが拡大となっております。\n６４ページです。３、女性福祉です。婦人相談員を配置しまして、相談業務を実施しております。\n６５ページをご覧ください。４、家庭福祉です。こちらのほうは、夫婦関係、離婚や相続、養育費の問題など様々な相談を行っております。\n隣の６６ページの（２）です。こちらのほうに、養育費相談支援事業です。こちらは、令和３年度より開始しており、相談件数は増加しているところでございます。\n次に、６７ページをご覧ください。５、ひとり親家庭福祉でございます。就労や子どもの養育環境の相談に応じ、自立援助を行っており、ひとり親家庭の経済的自立助成と児童の福祉の増進を目的として、貸付けも行っております。\nページが飛びまして、７３ページをご覧ください。６、ひとり親家庭支援事業でございます。こちらのほうはひとり親家庭にレクリエーションや学習支援など様々な事業を行っております。\n次に、７８ページ、７、入院助産でございます。こちらのほうは、経済的な理由により出産費用が困難な方へ助成をしているものでございます。\n続きまして、７９ページをご覧ください。８、奨学金貸付事業でございます。在学応援資金は、貸付額の全部または一部の返還を免除する制度がございます。入学準備金は、高校等入学に必要な費用についての貸付けをしております。\n８１ページ、９、子どもの未来応援事業でございます。こちらのほうは、子ども食堂の支援や、ふるさと納税型のガバメントクラウドファンディングを実施し、子どもの食の支援事業を行っております。\n８４ページから８６ページは、国の特別給付金の昨年度の実績を記載しております。"},{"i":56,"speaker":"立木保育課長","text":"私からは、保育課の事務事業について、保育教育運営担当課長と分担してご説明いたします。事務の分掌ごとにご説明しますので、ページが前後しますがご了承いただければと思います。\n最初に８７ページをご覧ください。保育園等の利用認定です。保育園等を利用する際は、利用のための認定を受ける必要がございます。（１）認定の種類に記載のとおり、３区分ございまして、８８ページに年齢別認定数を記載してございます。\n次に、８９ページをご覧ください。項目２の認可保育園でございます。こちらには保育園の目的、概要を記載しております。\n2)の施設整備の現況をご覧ください。令和４年４月１日現在の認可保育園は公立４６園と、私立１０３園で、合計１４９園でございます。定員は１万２,１０８人で、前年度より２３６人の増となっております。年別の在籍状況につきましては、９１ページから９３ページの表のほうをご覧いただければと思います。\n次に、少し飛びますが９４ページの特別保育でございます。区では基本保育のほかに様々な特別保育事業を実施しております。延長夜間保育をはじめ、休日保育、年末保育、病後児保育、病児保育などがございます。\n９６ページの5)病児保育事業におきましては、今回記載が間に合いませんでしたが、令和５年６月１日に新たな医療機関併設型のキッズベル品川を開設してございます。\n次に、９６ページの（５）特別支援保育でございます。心身に障害のある児童や心身の発達状態から配慮を必要とするお子さんについて、よりよい発達につながる保育や保護者相談を実施しております。各巡回相談等の実績は９７ページと９８ページに記載のとおりでございます。\n続きまして、９８ページから１０１ページが、保育園運営に係る事業費と保育料の概要でございます。令和５年４月１日から第２子の保育園等の保育料を無償化いたしました。\n次に、１０２ページをご覧ください。（７）給食と食育では、保育園の給食や食育の取組を記載してございます。\n（８）１日保育士体験におきましては、在園児の保護者が保育士の仕事を体験することで、子育てへの理解を深めてもらう事業でございます。コロナの間中断しておりましたが、令和５年５月から再開いたしました。\n１０３ページにございます、在宅子育て支援事業の（９）チャイルドステーション事業も同じく、令和５年５月から再開しております。\n次に、１０５ページをご覧ください。地域型保育事業について記載をしているところでございます。\n１ページ進んでいただきまして、１０６ページの中ほどをご覧ください。参考といたしまして、区内保育所等の定員数、在籍数、新規入園申込者等の状況を記載しております。ページ下部、参考2)のとおり、待機児は令和４年度に引き続き０となりました。\n次に、１０８ページから１１１ページでは、区立幼稚園並びに幼保一体施設について記載をしております。\n少し飛びますが、１１３ページをご覧ください。項目６、就学前乳幼児教育の充実でございます。０歳から就学前までの全ての子どもが、保育園・幼稚園の区別なく、等しく質の高い保育・教育を受け、小学校にスムーズに移行できるよう、乳幼児教育の充実に努めております。具体的には保育園職員の研修や関係施設との連携、また、指導検査や私立保育園等への巡回支援を行っているところです。\n１１５ページの（７）保育事業者労務状況分析業務等委託事業は、新規事業で、社会保険労務士の方々の協力を得まして、労務環境のよりよい改善のための助言を行ってまいります。\n次に、１１６ページをご覧ください。項目の７番、一時預かり事業でございます。在園児を対象とした区立幼稚園での預かり保育と、保護者が病気などの理由で子どもを保育できないときに、一時的に公私立の保育園でお預けする一時保育を実施しております。"},{"i":57,"speaker":"今井保育教育運営担当課長","text":"続きまして、私からは保育教育運営担当課長が事務分掌しております部分に関しまして、ご説明を差し上げたいと思います。\n恐れ入りますが、１０３ページ下段をご覧ください。（１１）区立保育園の建替え（大規模改修）の部分でございます。全ての保育施設の安全面については問題ございませんが、築４０年から５０年を超える施設が多い状況で、順次建て替えや大規模改修を進めるものでございます。\n次に、１０４ページ、（１２）区立保育園の民営化でございます。民営化ガイドラインに沿って、健全財政の維持および民間活力の活用という観点から、当面は、区立保育園５園の公設民営化を実施いたします。\n次に、少し飛びますが、１１１ページをご覧ください。後段（７）品川区立就学前乳幼児教育施設（ぷりすくーる西五反田）でございます。公設民営型の幼保一体施設でございまして、ふれあい交流室を併設し、地域の子育ての相談や支援を行っているところでございます。\n次に、少し飛びまして、１１９ページをご覧いただけますでしょうか。項目の８番でございます。子ども・子育て会議でございます。この会議は、子ども・子育て支援法に基づきまして、各種施策を推進するために必要な調査・審議など、実施を目的として設置しているものでございます。また、区立保育園等の今後のあり方についても、別途調査検討を進めておるところでございます。\n（２）品川区子ども・子育て支援事業計画でございますけれども、令和２年度から令和６年度におきましては、第２期事業計画に基づきまして、各種の子ども・子育て支援の取組を進めているところでございます。昨年度は中間年度ということで見直しを実施したところでございます。"},{"i":58,"speaker":"石井保育支援課長","text":"私からは、保育支援課の事務事業についてご説明申し上げます。\n事業概要１２１ページをご覧ください。まず、私立認可保育園の運営等でございます。こちらですが、区内私立保育園１０３園に対して運営費助成、そして、各種補助金の支給のほか、新規開設等の支援を行ってございます。\n令和５年度の新規事業といたしまして、１２３ページ記載の6)から8)、一時預かり事業、保育人材確保・育成支援事業、児童の安全確保支援事業ということで、私立保育園においてもリフレッシュ目的で一時預かりができるようになるほか、保育補助者の雇い上げや園外活動の見守り等を支援することで、私立保育園の質の向上を図ってまいります。\n続きまして、１２５ページをご覧ください。地域型保育事業の運営でございます。区内に合計２１園ございます、家庭的保育事業ですとか小規模保育事業に対する運営費助成と各種補助金の支給を行ってございます。\n続きまして、１２８ページをご覧ください。３番の認証保育所等でございますが、こちら、区内２１園ございます認証保育所に対する運営費助成と各種補助金の支給、また、保護者に対する保育料の助成を行ってございます。令和５年度につきましては、１３０ページに記載がございますけれども、保育料の第２子無償化に伴い、認証保育所保育料助成の助成額も、第２子以降は増額してございます。\n続きまして、１３３ページの中段ですが、ベビーシッター利用支援事業、こちら一時預かり利用支援ということでございますが、かなりご好評をいただいておりまして、令和４年度、新規事業でございましたが、１,１９０名のご利用がございました。\n続きまして、少し飛びますが１３７ページをご覧ください。４番の私立幼稚園でございます。こちら、区内１８園の私立幼稚園に対する各種補助金の支給、保護者に対する助成金の支給を行ってございます。令和５年度におきましては、１３９ページに記載がございます、（１０）ということで、入園児数の増加ですとか幼児教育の質の確保を図るために、私立幼稚園に対して広報宣伝活動費に係る費用の助成を計上してございます。こういったことから、幼児教育の質の向上に引き続き努めてまいりたいと考えてございます。\n続きまして、１４２ページでございます。在宅子育て支援事業ということで、ぷりすくーる西五反田の分も含めますと、区内１２園ありますオアシスルームの運営ですとか、ポップンルームの運営、あとは、空き店舗を利用した子育て交流ルームの運営助成を行ってございます。オアシスルームにつきましては、本年度、全施設においてキャッシュレス決済が可能となるほか、予約システムの新規開発を行いまして、より一層の利便性の向上を図ります。\n続いて、１４４ページでございますが、こちら、在宅子育て支援事業の中に、（４）として、保育所等の空き定員等を活用した未就園児の定期的な預かり事業を記載してございます。こちら、先月の文教委員会でも補正予算をご審議いただきましたけれども、主に未就園児を対象とした定期的な預かりを品川区でモデル実施をすることによって、幼児教育保育の質の向上に加え、在宅の子育て支援についてもきちんと取り組んでまいりたいと考えてございます。"},{"i":59,"speaker":"つる委員長","text":"説明が終わりました。\nこれより質疑を行います。\n本件について、ご質疑等ございましたらご発言願います。"},{"i":60,"speaker":"安藤委員","text":"９ページの現状と考え方についての意見をお伺いしたいのですが、まず、２段落目なのですけど、子育て家庭を全力で応援するという目的が、「子育て・教育で選ばれるしながわ」となっておりますが、これは子育て支援の本筋の目的なのかなという疑問があります。なぜ子育てで選ばれる品川というのを子育て支援の目的にしているのかを伺いたいというのが１点です。\nそれと、１０ページのほうなのですけど、下から１０行目に「今後は保育施設等のあり方など保育供給体制の適正化を進める」と書いておりますが、この適正化をするというのはどういうことでしょうか、伺いたいと思います。\nもう１点、まとめて言ってしまいますが、先ほど保育教育運営担当課長のご説明で、１１９ページの子ども・子育て会議の運営というところで、区立保育園のあり方についてもここで、みたいな話があったのですが、この子ども・子育て会議の中で審議されると、そういう意味なのでしょうか。それを確認させてください。"},{"i":61,"speaker":"柏原子ども未来部長","text":"品川区の子ども未来部で、子どもの支援、家庭への支援というところでの目標の部分というところでございます。「子育て・教育で選ばれるしながわ」といったところが一つ目標になっているというお話でございますけれども、安心して子育てができるという意味合いで、目標を立てさせていただいてございます。安心して子育てができるといったところで、ほかの地域の方であったりとか、そういった方々も、しながわであれば安心して子育てができるというところで、安心感を持っていただける、そういった子育てを施策として進めている品川区なのだ、といったところに目標を置いて、他区の人からもそういうふうに見ていただけるというのが、結果的にそういうふうになるといったところが、区の中の安心感といいますか安心した子育てができるという環境をつくるというところにつながっているということでの目標というものでございます。"},{"i":62,"speaker":"今井保育教育運営担当課長","text":"委員からのお問合せ、２点についてお答えいたします。\nまず、１点目が、適正配置についてはどういう内容を意味するのかというところでございますけれども、保育施設等のあり方など、保育供給体制の適正化を進めるというところを論点にいたしまして、どのような供給が適正なのかというところを検討してまいりたいと考えているところでございます。\n子ども・子育て会議とあり方の検討の位置づけの部分でございますけれども、子ども・子育て会議とはまた、別途ということで、別の場所で、今後の保育所等のあり方についての検討を進めていくといったところでございます。"},{"i":63,"speaker":"安藤委員","text":"最後のところは、主に、保育教育運営担当のほうで、そういう区立保育園のあり方については検討する所管というか中心になっていくということなのかというのをちょっと聞いたのですけど、そういうことでいいのか伺いたいです。\nそれと、適正化なのですけど、適正化ということは、子どもが減っているということの記述もありましたよね。それで適正化となると当然、減らすとなると思うのです。子どもの数に合わせて保育園を減らすということになれば、この面積基準や戦後ずっと変わっていない保育士の配置基準など、そういう子育ての質の強化という点でも、あとその少子化対策という点でもやはり逆行するのではないかと思うのですけど、これ最後の質問なのですが、適正化の下での認可保育園を減らすということはやはりやめるべきだと思うのですけど、いかがでしょうか。"},{"i":64,"speaker":"今井保育教育運営担当課長","text":"あり方の所管の部分ということでございますけれども、私、保育教育運営担当課長のほうで、子ども・子育て支援事業計画ですとか、区立保育所の整備など総合調整を所管しておるところでございますので、そういった提供体制のあり方、今後の計画といったところについては、私のほうで所管させていただいているといったものでございます。\nもう１点ですけれども、適正化というのが、保育園を減らしていくのかどうかというところでございますが、質の向上とかも含めまして、今後、保育園に求められていく役割ですとか、あとは、今後の保育需要がどう変わっていくのかというところも、もろもろ含めまして、今後、保育供給体制の適正化について、総合的に検証していきたいというふうに考えているところでございます。"},{"i":65,"speaker":"つる委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で、事務事業概要を終了いたします。\n────────────────────────────────────────────\n３ 報告事項\n(1) 教育委員の公募について"},{"i":66,"speaker":"つる委員長","text":"次に、予定表３の報告事項を聴取いたします。\n(1)教育委員の公募についてを議題とします。\n本件につきまして、理事者よりご説明願います。"},{"i":67,"speaker":"宮尾庶務課長","text":"それでは、私から、教育委員の公募について資料に沿ってご説明をさせていただきます。\nなお、本件につきましては、本日、総務委員会におきましても同様のご報告をさせていただいております。\nまず、資料の１をご覧ください。目的でございます。諸課題に対しまして、これまで以上に幅広い視野、柔軟な発想、こういったものを取り入れ、より開かれた教育委員会としていくことを目的に、このたび、教育委員の公募を行うものでございます。\n２番、効果でございます。地方教育行政の組織及び運営に関する法律では、教育委員の中に保護者が入っていることを定めております。今回、この保護者枠を公募することによりまして、子育て世代の意見を教育行政に取り入れられ、保護者の参画意識も高められるというふうに考えてございます。\n３番、募集内容でございます。（１）番、応募資格でございますが、1)番、品川区長の被選挙権を有していること、2)番、中学生以下の保護者であること、3)番、品川区の住民登録があること、4)番、法で定める破産、禁固刑などに該当していないことでございます。（２）番、任期は令和５年１０月１１日からの４年間。（３）番、選考方法は、１次選考で小論文、２次選考で面接を予定してございます。\n４番、スケジュールは記載のとおりでございますが、６月、今月に募集を行いまして、翌、来月７月に１次選考、８月、２次選考、９月に候補者を決定し、その後、区議会に任命同意の議案ということで出させていただく予定でございます。\nなお、この選考に係る一連の事務につきましては、区長部局において実施することを予定してございます。\n説明は以上でございます。よろしくお願いいたします。"},{"i":68,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":69,"speaker":"安藤委員","text":"教育委員会が、保護者や子どもや住民の要求をつかんで、自治体の教育施策をチェックしていけるようになるということはすごく大切なことなのではないかなというふうに思います。その上で、今回の選考ですが、１０月の頭で任期が切れる方が１名いらっしゃるので、１名ということの公募ということでいいのかということと、それと、選考というのは誰が行うのか、どんな基準で行うのか、選考委員会のメンバーを教えてください。何を重視するかなどの選定基準、これは決まっているのでしょうか。伺いたいと思います。"},{"i":70,"speaker":"宮尾庶務課長","text":"２点のお尋ねをいただきました。\nまず、１点目、今回は委員のお見込みのとおり、この１０月で任期が満了となる委員が１名おりますので、その方の後任ということで、１名の公募となります。\nそれから、選考に関する基準、メンバー等々でございますが、これはまさに今、こちらの基準を、策定を最終的にしているという段階でございます。"},{"i":71,"speaker":"安藤委員","text":"メンバーについても策定中というか選考中ということなのでしょうか。これから、公募をもう６月に始めて、今後締切りと、選考は７月ですけど、このタイミングで、今日この文教委員会で選考基準何も教えられませんというのは、ちょっと、ではいつ教えてくれるのですかというか、私たちとしても意見の言いようがないというか、全く決まっていないのでしょうか。伺いたいなと思います。\nあと、今回の替わる方は教育長の職務代理者も務めていらっしゃるようなのですけど、そういった職務代理者については、改めて教育委員会の中で選考し直すということなのか、それも併せて伺います。"},{"i":72,"speaker":"宮尾庶務課長","text":"繰り返しのご答弁になってしまいますが、メンバーそれから選考基準等々につきましては、現在、区長部局のほうで検討中であるというふうに聞いてございますので、今お示しできるのは、この資料に記載をしているところでございます。\nそれから、職務代理というところでございますが、現在、その先ほど申し上げました、１０月で任期が満了になる委員は、今現在、教育長の職務代理者を務めていらっしゃる委員でございます。今回、公募で選ばれた方がそのままということではなく、職務代理者につきましては改めて決定をするような形になるところでございます。"},{"i":73,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":74,"speaker":"高橋（し）委員","text":"確認したいのですけれど、今まで教育委員の方を区長がある程度選んで、議会のほうに同意を求めてきたのですが、そこに至るまでの委員の選考の過程を教えていただける範囲で教えていただきたいと思います。それが１つ。\nそれからもう一つは、今ちょっと話出たのですが、選考についての要綱なりができていない状態というのはすごく不思議な状況で、それが無い中であと、開始がいつだか分かりませんけど、それについては、どれぐらいのスパンで決めていくのかというのを区長部局でどういうふうにお話ししているかは、教育委員会に伝わってきていないなら来ていない、伝わっているならばどのくらい伝わってきているのかお尋ねします。\nそれからもう一つは、レイマンコントロールは教育委員会の非常に重要な仕組みだと思っていますので、一般の方々のご意見がこういった行政の中で必要だというのは大変重要だと思っているので、公募するということに関して反対しているわけでは全くありません。それで、保護者の方を公募するということは、今の選考の仕方、つまり選任の仕方のどこに問題があって、それをどう改善するために公募するのかということをお尋ねします。\nとすると、次は、全部で４人いらっしゃるわけですけど、ほかの方々とのバランスというか、今後どのようにバランスを取りながら、教育委員の方を選考していくかという展望というか、そういうのがあって、当然、今回保護者の枠を決められたと思うので、その点について区長部局が検討しているならば、どこまで教育委員会に来ているか、全く来ていないなら来ていないで結構ですけど、そこを教えていただければと思います。\nまず、そこまでお願いします。"},{"i":75,"speaker":"宮尾庶務課長","text":"何点かお尋ねをいただきました。\nまず、これまでの選考の過程というところでございますけれども、基本的には委員のお話のとおり、区長のほうから議会のほうに人事案をご提出させていただくというところで、区長部局のほうで選考はしておりましたが、必要に応じて教育委員会からも、例えば相談をいただいた場合には、法律の趣旨等に基づいて、適任の方を、例えばご提案というかお話をさせていただくということもございました。ただ、最終的に、その方をどうするかというところは、区長部局のほうで、当然ですが決めていったというところでございます。\nそれから、スケジュールのところでございますけれども、現時点では、私どものほうにも、６月中に開催をすると、募集事務を始めるというところまでの情報のみ来ているところでございます。その中で、様々協力する場面があれば、させていただいているというところでございます。\nそれから、なぜこの公募に至ったかというところでございますけれども、ちょっと資料と重複をしてしまいますが、これまで以上に、様々な諸課題に対して幅広い視野、それから柔軟な思想を持った方というのをこれまで以上に取り入れていくという必要性から、今回の公募を実施するに至ったというところでございます。\nそれから、最後に今後の展望というところでございますが、まず、今回、１０月で任期満了になる方の後任というところで、その後のことについてはどうなるかというところはまだ、区長部局からも特に決まったというようなお話はいただいておりません。まずは、今回のこの１０月の公募に向けてというところでございます。"},{"i":76,"speaker":"高橋（し）委員","text":"それぞれ、区長部局から様々詳しいことが来ない中で進められているという状況で、事務局がある教育委員会はその道の専門の方でいらっしゃるわけですから、そこがちょっと入っていないでこの公募が進めていかれる、悪いと言っているわけではありません、公募することはいいと思っていますから、そこがちょっと疑問に思っているというところです。\nその中で、これまたちょっと区長部局の話で議論できないのかなと思うのですが、小論文や面接でこういった、その方のすばらしさが分かるのかということ、それから、あと、応募した方の中での相対評価になるわけですよね。今までは、相談を受けて、ただ、こういう方がいる、こういう方がいるというので、いろいろ区長部局とやりながら決めていったわけですけど、応募した方の中から決めるという点が１つ。もう一つは、仮に適する方がいらっしゃらなかった場合はどうするのか。これは区費教員のときも一緒なのですけど、その中からどうしても人を選ぶのかというところの議論があるかと思うのですが、その辺りについて、実は文科省の公募についての課題という、いろいろなポイント整理の中に出ているのですけど、そこの点についてはいかがでしょうか。"},{"i":77,"speaker":"宮尾庶務課長","text":"まず、今回は、委員のお話のとおり、応募者の中から決めさせていただくということを前提に考えていると聞いております。\nそれから、適任者がいなかった場合というところでございますが、委員のお話ありました、その国の考え等も踏まえてやっていくものというふうに捉えているところでございます。"},{"i":78,"speaker":"高橋（し）委員","text":"長々とすみません。ありがとうございました。そういった状況なので、また、担当部局のほうに聞く機会をつくってお尋ねしたいと思います。いろいろ、ご答弁ありがとうございました。"},{"i":79,"speaker":"石田（し）委員","text":"１点だけ、今のことに関して、これはでは、今回のこの公募について、教育委員会はどこまで関与するのでしょうか。今のご答弁を聞いていると、基本的には区長部局がやるということで、教育委員会の関与はほとんど見られないのですけど、どこまで関与しているのかだけ改めて教えてください。"},{"i":80,"speaker":"宮尾庶務課長","text":"これまでも、この公募を行うに当たっては、区長部局側からいろいろなご相談、それから照会等をいただきまして、区教委として協力できるところはしっかりと協力をしてきたというところでございます。また、これもまだ、どうなるかというところはあるのですが、例えば選考の中で、あるいは教育委員会のほうに何か依頼があるということも想定はされます。まだ、この辺は、それも含めて今、区長部局のほうで検討中であるというふうに聞いてございます。"},{"i":81,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":82,"speaker":"安藤委員","text":"ちょっと１点確認したいのですけど、今回の教育委員の公募について、いわゆる定例の教育委員会があるではないですか。そこでこれまで議題として出たということがあったのか。それはどんな審議があったのか、なかったのか、あったとしたらどういうような意見が出たのか、ない場合はこれから審議とかの予定があるのか。そこも含めてお願いいたします。"},{"i":83,"speaker":"宮尾庶務課長","text":"これまで、教育委員会での取扱いというところでございますけれども、これまで議題等として出たことはございません。明日開催予定の教育委員会の定例会において、ご報告という形で委員の皆様にお話をするという予定でございます。"},{"i":84,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":85,"speaker":"吉田副委員長","text":"１点だけ確認させてください。今、６月中に事務を開始するということで、このスケジュールを見ると、６月中にはもう公募開始というふうになっております。もう６月ももうすぐ半ばというところで、どこにどう向けて公募するのでしょうか。すみません、初歩的なことなのですけれども、どうしてもその応募者の中からメンバーを決めるとなると、しかるべき方にはぜひ公募に応じていただきたいというふうに思うのですが、その辺、どのような形で公募をされるのかを知りたいです。"},{"i":86,"speaker":"宮尾庶務課長","text":"その辺は、どのような形で公募を具体的に行っていくか、それからどのタイミングでというところも含めて、今まさに区長部局のほうで詰めているというふうに捉えておりますので、そこのところはそのようなご理解でお願いできればと思います。"},{"i":87,"speaker":"つる委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(2) 文化財の指定・登録について"},{"i":88,"speaker":"つる委員長","text":"次に、(2)文化財の指定・登録についてを議題に供します。\n本件につきまして、理事者にご説明願います。"},{"i":89,"speaker":"宮尾庶務課長","text":"それでは、引き続き私から、文化財の指定・登録についてといたしまして、最近区内で文化財として指定登録されたものについてご報告をさせていただきます。\n資料をご覧ください。２件ございます。\nまず、表面でございます。１件目、東海道品川宿石積護岸でございます。\n本文化財の所在地は南品川２－１４－１０で、こちらは個人宅でございます。区分でございますが、品川区指定の史跡、指定日は令和５年３月２９日でございます。\n（３）指定理由でございます。本石積護岸は、江戸時代に品川宿の東海道を波濤から守るために築造されたものでございます。現存する石積は、写真を資料に記載してございますが、文献資料、発掘調査の結果から、１９世紀前半以前に構築されたものということが分かっております。このような石積護岸は、江戸時代、高輪から大森にかけての東海道の海岸線上に存在しておりましたが、既にその多くは宅地開発などによって消失をしております。本地点は、残存する中でも保存状態がよく、特に江戸時代に構築された石積がこのように地上に露出をしているというのはこの地点のみでありますことから、江戸時代の土木技術をうかがうことができる希少な事例であるということが言えるかと思います。\n裏面をご覧ください。２つ目、旧品川警察署品川橋交通待機所でございます。\n所在地は南品川１－３－４。登録区分でございますが、国登録の有形文化財のうちの建造物。登録日ですが、所管する文化庁からは、令和５年６月中、今月中を予定していると聞いてございます。なお、本件は、去る令和５年３月１７日に、文化庁の文化審議会から答申が出されております。\n（３）概要および登録理由でございます。本建物は、旧東海道の交通要所として往来が盛んな同地の安全確保のために、地域住民の方々が中心となって、昭和４年に品川警察署品川橋巡査派出所として建てられたものでございます。建物のデザインから交番としての機能性がうかがえる一方、施工当時に流行していたアール・デコの意匠がしのばれます。同様の交番建物は都内での残存事例が少ないこと、また、関東大震災後に耐火構造で建てた戦前の交番遺構として、また、昭和初期の品川宿の景観を現在に伝えるものとして、貴重な歴史的建造物であると言えます。\n資料３ページ目には、位置図をつけてございます。それぞれ赤くマークをしておりますところが、それぞれの所在地でございます。"},{"i":90,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":91,"speaker":"安藤委員","text":"これ、それぞれ指定されると、どういった縛りというのですか、義務というのですか、そういうのが発生するのかというのをそれぞれ教えてもらいたい。\nそれとあと、審議会があるのですけど、この２つが具体的に、指定の対象にという候補として挙がると思うのですが、審議会の中で審議もされるのかなと思うのですけど、挙がっていく過程というのですか、どういう流れでこういう候補になっていくのか、その辺もし分かれば教えてください。"},{"i":92,"speaker":"宮尾庶務課長","text":"まず、それぞれにつきまして、この指定・登録された後の縛りというか規制というところでございますけれども、まず、品川宿の石積護岸のほうは、こちらは区の指定ということになりますので、基本的に手を加えることというのはできません。このまま大切に保存をしていただくということがベースになります。もちろん、これを保つために、修理、修繕をするために最小限の手を加えると、これはもう当然にやりますけれども、基本的にはこの形のまま後世に残していく、これが原則となります。\n対しまして、品川警察署の品川橋の交通待機所は、こちらは国の登録制度というところで、指定よりも若干緩やかな縛りといいますか規制になります。例えば、具体的に言いますと、こういった建造物の場合には、中に手を加えて、実際こちらは今、観光案内所としてご利用いただいているのですけれども、そういったように中に手を加えて、例えば観光のために手を加えるということは許されております。大きく外観が、形が変わってしまうようなところは規制があるのですけれども、指定に比べると緩やかな縛りということが言えるかと思います。\nそれから、それぞれここに至るまでの過程、経過というところでございますけれども、石積護岸に関しましては、前々からこちらにこういった貴重なものがあるということは、私ども区のほうでも認識をしておりました。直接のきっかけとなったのが、このお宅の前、これ区道になっているのですが、ここで道路の工事をするときに、ちょっと我々区の職員が工事の立会いをさせていただいたということがございまして、それがきっかけで所有者さんと、いかがでしょうかというような話をさせていただきまして、こちらは個人のお宅でございますので、まず、その所有者の方のご理解、それからご承認がいただけるということ、これはもう大前提になりますので、そこから、我々のほうで詳しい調査をさせていただいたり、あるいは文化財保護審議会のほうでも詳しく調査をさせていただいたりということで、最終的に、審議会のほうから、これは保存にふさわしいというお答えをいただきまして、ここに至ったというところでございます。\nそれから、交通待機所のほうでございますが、こちらは、国の登録というところで、地元の地域のまちづくりの協議会の方々たちから、どうでしょうかというようなお話をいただきました。それで、私どものほうで国につながせていただいて、国のほうで詳しい調査をして、今回この審議会の答申が出されたというところでございます。"},{"i":93,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":94,"speaker":"高橋（伸）委員","text":"ご説明ありがとうございました。\n石積護岸のところなのですけども、今、課長ご説明あった話では、区道の工事があったからこういうふうないきさつというのを今ご説明いただいたのですけども、私も現場行ってみたわけではないのですけど、写真で見ると、この既存の建物というのは最近何か新築したのではないのかなということがあるので、それに伴う区道工事で、これからこういう視点に立ったという解釈でよろしいのですか。"},{"i":95,"speaker":"宮尾庶務課長","text":"確かに委員おっしゃるとおり、写真をご覧いただくとお分かりかと思うのですが、この護岸の上に立っている所有者様の建物、比較的新しく見えるかと思います。直接、きっかけになったのは、先ほど申し上げたとおり、この写真に写っている護岸の前の道路工事がきっかけになったのですけれども、そことほぼ時期を同じくして、所有者様もこちらの建物の建て替えを行っております。そのタイミングでやはり、こちらに影響のないようなことができるかというようなところもご相談をさせていただいて、所有者もこちらを大事に思う気持ちというのが同じで、ここに影響のないように建て替えを行っていただいたと。そのときに、こちらの壁の後ろ側からもしっかりと補強した上で、建て替えを行っていただいたということ、経緯がございます。"},{"i":96,"speaker":"高橋（伸）委員","text":"分かりました。ありがとうございます。この石積と、これは本当、江戸時代の土木技術をうかがうことができるということと、交通待機所は、これは歴史的建造物であることを踏まえて、これ文化財の指定登録なのですけども、所管は違いますが、建築課でオープンしなけんとか、そういう史跡回りとか、そういうこともやっているではないですか。今後、そういうのも担当の所管とも連携していただいて、より区民の方に分かってもらえるようなことをしていただきたいと思いますので、これは要望なので、よろしくお願いします。"},{"i":97,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":98,"speaker":"吉田副委員長","text":"先ほどのご説明で大体は分かったのですけども、結構これ、要は個人の所有権とか私権が制限されるのではないかということを、私の会派でも懸念の声が出たのですが、それで先ほど、補強とか、ここに影響がないような形で新築していただいたとかいうときに、全てやはり所有者さんの思いで、要は、区としても何か、これを残すための補助とかが今後もあるのかとか、それからこれからも残すとなれば、やはり、特に石積だといろいろ補強とかも必要になってくると思うのですが、その辺の私権とそれから区の関わりというところで教えてください。"},{"i":99,"speaker":"宮尾庶務課長","text":"こちら、もう指定にご協力をいただいて、無事指定という運びになったのですけれども、これから、例えば大きく、これを守るために何か修繕とか工事とかを行うという場合には、こちらのほうで補助金という形で金銭面でのサポートをさせていただきます。それ以前に、もちろんオーナーさんからいろいろなご相談事がおありかと思うのですが、その際は区のほうでしっかりと丁寧に対応させていただきたいというふうに考えております。"},{"i":100,"speaker":"吉田副委員長","text":"そういう意味で、補助が出るということではちょっと安心をしたのですけども、先ほどの、そもそもこれを指定するに当たっては、その所有者の同意がなければ基本難しいということですよね。もし、同意があれば、今後もそういう、区としての補助金とかということも想定しながら指定をお願いするということでよろしいでしょうか。\nそれで、今後ですけど、相続とか発生しますよね。多分というか、いつか必ず発生すると思うのですが、そういうときにはまた、相続する人との協議とかということが行われると理解してよろしいのでしょうか。"},{"i":101,"speaker":"宮尾庶務課長","text":"委員のお話のとおり、今の所有者様から代が替わって相続等されたときには、そのオーナーの方が、所有者の方が変わるという手続が必要になります。当然その手続の過程で、現オーナーとそれから相続をされるオーナーとの間で、もちろんそこでしっかりと引き継いでいただくのが望ましいことではあるのですが、場合によっては私どもの区のほうがご相談に入らせていただいて、文化財としてスムーズに引き継いでいただけるような相談、それからご支援をさせていただく、今までもほかの物件でもそのようにさせていただいているところでございます。"},{"i":102,"speaker":"つる委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(3) 学校改築の進捗について"},{"i":103,"speaker":"つる委員長","text":"次に、(3)学校改築の進捗についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":104,"speaker":"森学校施設担当課長","text":"私から、学校改築の進捗についてご説明いたします。Ａ３横の資料をご覧ください。\n令和５年６月現在の状況ですが、小学校６校、中学校１校の改築を進めております。\n資料の左上をご覧ください。浜川小学校では現在、校舎棟の躯体工事を進めており、令和６年３月に校舎棟が完成する予定です。その下、第四日野小学校では現在、校舎棟の仕上げ工事を進めており、令和５年７月に校舎棟が完成する予定です。その下、浜川中学校では現在、体育館棟の躯体工事を進めており、令和５年１１月に体育館棟が完成する予定です。右上、城南第二小学校では、現在改築工事契約議案の上程準備中であり、令和５年８月から工事に着手し、令和７年度に校舎棟が完成する予定です。その下、源氏前小学校では、令和４年度に基本設計を行いまして、現在、実施設計に着手しております。基本設計の内容につきましては、この後概要をご説明いたします。その下、鈴ケ森小学校では、プロポーザルの結果、設計委託業者を選定いたしましたので、現在、委託契約手続を進めております。その下、浅間台小学校では今年度、改築工事の準備として、敷地測量に着手いたします。\nそれでは、１枚おめくりください。\n資料の左上より、源氏前小学校の校舎改築の計画概要でございます。建物概要はここにお示ししているとおりです。地上５階建てとなっております。教室数ですが、普通教室１８室プラス多目的教室が６室の合計２４室で計画しております。\n次に、計画のコンセプトは、１から４のとおりとなってございます。資料中央上、配置兼１階平面図をご覧ください。図面上側が北になります。南門が面している南側道路が、荏原町商店街である三間通りで、正門が面している東側道路から２５０メートルほど北側に東急大井町線中延駅がございます。敷地の南側に校舎を配置し、敷地北側にグラウンドを配置しております。１階には保健室、職員室、特別支援教室、和室、給食室や多目的ホールを配置しております。\n資料右中央２階平面図です。普通教室を南に配置し、体育館、メディアセンター、多目的室を配置しております。その上、３階は普通教室と理科室、音楽室を配置しております。その上、４階は普通教室と家庭科室、図工室を配置しております。その上、５階はプールとプール諸室を配置しております。\n最後に、資料中央下、建替計画でございます。ＳＴＥＰ１をご覧ください。グレーの部分が既存校舎です。敷地東側に逆Ｌ字型の既存校舎が配置されており、東側には既存体育館棟が配置されております。ＳＴＥＰ１、敷地西側にある既存プールや旧校舎の基礎等地中埋設物を撤去します。ＳＴＥＰ２、体育館を含む新校舎を建設します。ＳＴＥＰ３、北側、東側の既存校舎、既存体育館棟を解体します。ＳＴＥＰ４、残りの校舎を建設し、ＳＴＥＰ５、グラウンドを整備して完成です。\nなお、体育館は工事期間中、新旧いずれかを使用できる計画となっております。また、建替工程につきましては、これから実施設計を行いますので、若干の変更等があることをご了承ください。"},{"i":105,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":106,"speaker":"安藤委員","text":"源氏前小について伺いたいのですが、建て替える前と後というのは、延床面積はどれぐらい変化があるものなのか。あと、校庭の大きさというのはどんな変化があるのかというのをお伺いします。\nそれと、こういう建て替えの場合は、ちょっとここは難しいかもしれません、分からないですけれども、隣地の、隣接する敷地があれば、やはりできれば購入できる所があれば、併せて敷地を増やしてということが、大変教育環境上も有効だと思うのですけど、そういうことというのは建て替えに併せていろいろ調査とかしているものなのかというのを伺います。\nそれと、この、昨年度の文教委員会で、いわゆる一足制という報告があったのですけども、人工芝でというところは、少しずつ、上履きに履き替えない一足制というのを考えていきたいみたいな姿勢が、区教委のほうの報告からあったように記憶をしているのですが、今回の源氏前のほうというのは一足制を考えていらっしゃるのか。\n以上４点伺います。"},{"i":107,"speaker":"森学校施設担当課長","text":"数点ご質問いただきました。\nまず、建て替え前と後の床面積等なのですけれども、既存の床面積４,３００平米ほど、新校舎が８,７００平米ほどですので約倍ほどになってございます。それと、グラウンドの広さですけれども、こちら今２,１００平米になっております。新校舎は２,２００平米で、ほぼ似たような広さなのですが、プラス庭園の部分が２００平米ほど増えますので、今のグラウンドより少し広いという状況に変わってまいります。\n続きまして、隣地の部分なのですけれども、隣地の購入等非常に、できるところであれば積極的に行っていきたいところなのですが、今、建て替えに伴いまして敷地の境界確定を行っております。今まではなかなか敷地が不明なところもあったのですけれども、敷地を確定しながら建て替えの準備を行っているところでございますので、建て替えに準じまして敷地がしっかり明白になっているような状況が進んでおります。\n最後に一足制なのですけれども、こちらの学校はできればその一足制を導入したいというふうに考えてございまして、１階の平面のところをご覧いただきますと、昇降口の所が、今までですと下足入れの部分がかなり大きい面積を占めていたのですけれども、この辺を合理化いたしまして、昇降口を一定程度の広さとして、それ以外の室を広めに取るということで居室を増やしたいというような考えで、今のところ設計はしておるところでございます。"},{"i":108,"speaker":"安藤委員","text":"一足制にもメリット、デメリットあると思うのですけど、今の課長のお話ですと、もう既に一足制を導入することを前提としてつくっているという感じだったのですが、やはり子どもの権利条約では、子どもに影響を及ぼす事柄については意見を聞く権利があるというふうに定めているわけですし、教育委員会としては、できればそれを保障する立場に立つべきだと思うので、実際に今は二足制なわけですけども、ただこれ建て替えに随分時間がかかるので、そこが実際に使えるというふうにならないかもしれないのですけど、ただ、やはりちょっと、この当該学校に通っているお子さんのアンケートとか、意見を聞かれたという体験自体がすごく大事な経験になると私は思うし、自分たちが自分たちの周りの環境を主体的に考えて働きかけていくこともできるという経験にも、教育的にはすごくいいことだと思うのです。\nですから、ぜひ、その検討に当たっては子どもの声を聞いていただきたいと思うのですけど、いかがでしょうか。"},{"i":109,"speaker":"森学校施設担当課長","text":"委員ご指摘のとおり、子どもの意見を聞いていくというところでございますけれども、当該学校にもそうですし、今、実験的に一足制を導入している学校が数校ございます。そちらにつきましてもアンケートを取りまして、実際どうなのかというところは、児童・生徒に聞いてまいりたいというふうに考えております。"},{"i":110,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":111,"speaker":"高橋（伸）委員","text":"２点質問をさせていただきます。\nまず、１点目が、本年の１１月からプールの解体工事があるということです。これ期間がどれぐらいかかるのかということと、それに伴って、埋設物撤去があるような記載があるのですけども、これ事前に埋設物があるのかお分かりになっているのかというのがもう１点です。あと、それと、これ解体工事で、ここ今西門がありますけども、この西門が恐らく解体に伴う工事で閉鎖になると思いますけれども、そこの解体部分を含めたところをお聞きしたいです。\nあと２点目なのですけど、今度、学校の校舎が南側になるということで、今と真逆になりました。それで、グラウンドも広く多分使われて、とても使いやすくなるのかと思っておりますが、これ、人工芝になることによって、ここは荏原第四地区の拠点になっている、夏まつりであったりとか総合防災訓練とかあると思うのですけども、今実施段階で、これからご検討なされると思うのですけども、それは実施の方向で考えていいのかということだけ、その１点お聞きしたいと思います。"},{"i":112,"speaker":"森学校施設担当課長","text":"まず、プール解体の期間ですけれども、半年間、６か月ほどを考えております。その際、プールの近くの埋設物も撤去するわけです。この埋設物なのですけれども、実際は調査ができないので分からないのですが、過去の資料を見ますと、ここに何か建物があったことは分かっております。また、旧校舎だと分かっていますので、恐らく間違いなく出てくるだろうというふうに想定をしております。ですので、埋設物の撤去の期間も見込んでおりまして、解体、撤去をしていくという考えでございます。\n西門ですけれども、委員ご指摘のとおり、一旦閉鎖をして、こちら工事用出入口というふうになりまして、児童の皆様は東側からというふうにする予定でございます。\nそれと、人工芝のところと夏まつり、それから防災訓練等につきましては、できるように検討を今しておりまして、まず、一番ポイントになってきますのが恐らく、お祭りのときに煮炊きをどこでするのかというところなのですけれども、これは配置平面図をご覧いただきまして、図面の左上、黒い、西門に近いところなのですけれども、こちらはインターロッキングブロックという燃えないタイルのようなもので仕上げる予定になってございまして、起震車であったりとか、煮炊きも可能な場所にしてございます。\nそれで、飲食をどこでするのですかというところなのですけれども、この建物、黒三角のすぐ下に多目的ホールがあるかと思います、こちらでと思っています。それが、一足制もできることになれば、建物の中に入ってきて、飲食していただくこともできますし、そういうのを含めて、お祭りはこの辺でできるだろうと。\nそれから、防災訓練についても、人工芝が、今考えているのがノンフィルタイプというフィルが入っていないタイプですので、ホースを下に向けますとちょっと問題があるかもしれませんが基本的にできるだろうというふうには考えておりますので、防災訓練も恐らくこの場所でできるのではないかというふうに考えてございます。"},{"i":113,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":114,"speaker":"ゆきた委員","text":"こちら、図面を確認しますと、体育館が２階に計画されているのが確認できますが、体育館は避難場所として開設して、開放されることになると思われます。２階が避難場所となると、障害者とか高齢者の方の負担になると思われますが、こういった負担の面と、あと水防対策として、他区でも２階に体育館をつくられているということもありますが、品川区では区の中の海抜が、源氏前小学校は１７.８メートルということで、わりかし高いところにあるのですけども、こういったところは水防対策として考えて計画されているのか、もし分かる範囲であればお答えいただければと思います。\nまた、２点目として、すまいるスクールの位置が確認できなかったので、こちらも分かれば教えていただければと思います。"},{"i":115,"speaker":"森学校施設担当課長","text":"２階の体育館のところなのですけど、基本的にはバリアフリーで建物はできておりますので、障害のある方、高齢者の方、避難ができるようになってございます。\n２階に体育館を持ってきた理由なのですけれども、海抜は高いのですが、すぐ近くに過去、もう暗渠化しているのですけども立会川がございまして、水防的に２階に体育館、水没してしまったら避難できませんので、そういうこと含めまして２階に体育館を設置してございます。\nすまいるスクールなのですけれども、今現在検討している段階でございまして、１階の多目的室のところか２階かというところで今、検討しているところでございます。すまいるスクールがないということはございません。"},{"i":116,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":117,"speaker":"吉田副委員長","text":"具体的にどの学校ということではなく、改築のときの進捗の管理ということなのですが、区民の方からご意見いただいて、その方は、既に今改築中の学校にお子さんが通っている。それで、問題は、非常に騒音とそれから臭いがすごくしてきて、授業についても差し支えがあるということなのですが、そういうご意見を持たれた方はどこにどういうふうに、教育委員会事務局でいいのか、その辺確認させていただきたいのですけど、いかがでしょうか。"},{"i":118,"speaker":"森学校施設担当課長","text":"工事中の騒音、臭い等の問題というところでございますけど、庶務課の学校施設整備担当、または学校施設担当課長の私で結構でございますのでご意見いただければ、できる限り対応していきたいというふうに思っております。\n基本的には騒音、振動が少ない重機を使ったりですとか、臭いの少ない材料を選定してはいるのですけれども、どうしても近いところで工事を行っておりますので、そういう問題も起きてしまう場合もあるかと思いますけど、その際は庶務課のほうにご連絡いただければ対応いたします。よろしくお願いいたします。"},{"i":119,"speaker":"吉田副委員長","text":"分かりました。その方にぜひ、お電話で大丈夫ですか、ご連絡するように言います。それで、具体的にはなるべく騒音がないような形でという一方、やはり工事ですからどうしても騒音はね、だからその方もそれは想定しておられるのですけど、具体的にもお子さんが授業の声が聞こえないと。だから、本当に工事をやめろとかということではなくて、例えば、先生がマイクを持って話をするとか、それから工事中なので校庭で遊べないので、本来学校は、廊下は走ってはいけませんというところなのでしょうけど、子どもたちが体を動かせるような機会と、場所の配慮をお願いできないかということだと思うのです。もっと詳しくは当事者の方にご相談するように言いますけれども、もし、今の段階でご見解とか何かあれば伺いたいと思いますが、いかがでしょうか。"},{"i":120,"speaker":"森学校施設担当課長","text":"今、工事期間中でもコロナの対応で、もう今は減ってきているはずなのですけど、窓を開けていたりということもあったのかなというふうに思ってございます。例えば、授業中は窓を閉めていただいて換気は休み時間にしていただく等、そういう対応もできるかなというふうには思っております。\n体を使って遊んだり、動かしたり、というところでございますけれども、工事期間中、少なくとも体育館は新旧どちらかを使えるような配慮をしておりましたり、場所によっては、小さい規模になりますけれどもグラウンドを整備したりすることで、できる限り運動ができる、それと、ボルダリングウォールを設置する等で体を使っていただければというふうに考えてございます。"},{"i":121,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":122,"speaker":"高橋（し）委員","text":"設計などは順調にいくと思うのですけど、工事がどうしてもずれ込んだりしていると思うのですが、現在工事を３校でやられているのですけど、それぞれどれぐらい工事がずれ込んでいるか、計画どおりいっていれば計画どおりなのですか。そして、今後の見込みをそれぞれお願いします。"},{"i":123,"speaker":"森学校施設担当課長","text":"現在は、各工事なのですけれども、全体工程に影響はないというふうに聞いてございます。細かいところでいきますと、２週間ほど遅れていたりというのはありまして、それにつきましては、基本的には土曜日、日曜日、祝日休みなのですけれども、少しその辺は作業をさせていただいて、工期を巻き返すような努力をしているような状況ということでございます。全体工期が延びるということは現在のところ聞いてはございません。"},{"i":124,"speaker":"高橋（し）委員","text":"ということは、ここで資料いただいた校舎完成など、事実上校舎が完成することがやはり、在校生にとっては日常の授業の確保になるので、ここの浜川小学校、第四日野小学校、浜川中学校、校舎の完成はこの予定どおり、現状で考えるといけるということで確認、もう一度お願いします。"},{"i":125,"speaker":"森学校施設担当課長","text":"委員のお見込みのとおりでございます。"},{"i":126,"speaker":"つる委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(4) 令和５年度学級編制について"},{"i":127,"speaker":"つる委員長","text":"次に、(4)令和５年度学級編制についてを議題とします。\n本件につきまして、理事者よりご説明願います。"},{"i":128,"speaker":"柏木学務課長","text":"それでは、令和５年度の学級編制についてご報告いたします。\n表の説明に入る前に、学級編制全般についてでございますが、義務教育水準の維持・向上に資することを目的に法律が定められております。こちらの法律は令和３年度に改正されまして、小学校の学級編制が４０人から３５人に引き下げられました。人数の引下げについては段階的に行われ、令和５年度、今年度につきましては、１年生から４年生が３５人学級、５年生以降は４０人学級となっております。令和７年度に小学校の全ての学年が３５人学級になる予定でございます。\nそれでは、表の説明に入らせていただきます。\n１ページ目、小学校・義務教育学校（前期課程）でございます。初めに、表の見方でございますが、左から、番号、校名、児童数、学級数となっております。なお、表の真ん中ほどに水色の網かけの特別支援の欄には、特別支援学級、特別支援教室の児童数、学級数を記載しております。通級は山括弧、特別支援教室の拠点校につきましては括弧で記載をしております。表の中で、ピンクの網かけをしている部分がございます。こちらが、表下にございますが、区の判断による弾力的運用を行ったものとなります。具体的には、９番の第四日野小学校、３４番の八潮学園でございます。\n今年度の小学校・義務教育学校（前期課程）の全体の状況でございます。表の一番下に児童数の合計がございます。新１年生は２,９８７人、昨年度と比べて１９６人の減となっております。普通教室、在籍の児童数の合計は１万７,５１３人、昨年度と比べて１９３人の増となっております。\n次に、学級数でございます。新１年生は１９６人、昨年度より減りましたが、１０５学級、昨年度と同数の学級数となっております。普通教室の合計は５８５学級、昨年と比べて１６学級の増となっております。\n特別支援でございます。特別支援学級の児童数は１９３人、昨年と比べて１１人の増。学級数は３０学級、昨年と比べて２学級増となっております。括弧で示しております特別支援教室、通級の児童数は７２８人、昨年と比べて５２人の減。通級の学級数は７学級、昨年度と同数となっております。\n続きまして、２ページ目、中学校・義務教育学校（後期課程）でございます。中学校につきましては、法的には４０人学級となっておりますが、東京都の基準で７年生については３５人学級の対応のため、教員の加配措置等が実施されております。そのため、７年生については、学校に応じて学級増、もしくは教員の加配、いわゆるチームティーチングのいずれかを選択できるようになっております。表の見方は小学校と同じです。表の７年生で、黄色い網かけ、こちらは学級数の増を選択した学校となります。１番の東海中学校、６番の荏原第一中学校でございます。濃い青の網かけ、こちらは学級数を増やさずに教員の加配を選択した学校となります。２番の大崎中学校、１０番日野学園、１５番豊葉の杜学園でございます。また、ピンクの網かけ、こちらは区の判断による弾力的運用を行ったもので、８番荏原第六中学校となります。\n今年度の中学校・義務教育学校（後期課程）の全体の状況でございます。表の下、生徒数の合計ですが、新７年生は１,６８５人、昨年度と比べて１７人増、普通教室在籍者の生徒数合計は５,０４３人、昨年度と比べて２３人増となっております。\n次に、学級数ですが、新７年生は１７人増えましたけれども、５２学級、昨年と比べて１学級の減。普通教室の合計は１５２学級、昨年度と比べて同数となっております。\n特別支援でございます。生徒数は１４６人、昨年と比べて５人増、学級数は２３学級、昨年と比べて１学級増、特別支援教室、通級の生徒数は１２７人、昨年と比べて１３人減、通級の学級数は１学級、昨年度と同数となっております。\n簡単ではございますが、私からの報告は以上でございます。"},{"i":129,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":130,"speaker":"安藤委員","text":"まずは小学校なのですけど、クラスの標準の３５人学級よりも細かく分ける措置をしているのが第四日野小学校ということですね。逆に、クラスを増やさなかったのが八潮学園と。昨年までは、三木小学校で３５人学級からさらに細かく、小さいクラスにしていたのですが、それは何かなくなってしまいました。それぞれの、こういう措置をした、弾力的に運用した理由というのは、区としてはつかんでいるのか。そういう弾力的運用を申請というか相談してきた学校というのはほかにはなかったのか伺いたいと思います。"},{"i":131,"speaker":"柏木学務課長","text":"弾力化した学校の理由でございます。小学校でいうと第四日野小学校、あと、中学校のほうで荏原第六中学校、こちらについては、配慮が必要な児童・生徒が一定数いるということで、きめ細やかな指導を行うため、弾力化をしたいということで申請がございました。\n八潮学園ですが、こちらは年度当初に急な転入がございまして、そのため、本来ならば学級増なのですけれども、学級の整備に時間を要するということで、学級数を増やさない弾力化という形を申請してまいりました。\nほかに申請があったのかということですが、ほかにはございません。"},{"i":132,"speaker":"安藤委員","text":"そうですか。何か配慮が多い児童・生徒が一定数いると、ほかにもあるのではないかなと思うのですが、申請はないということで、そういう制度が知られていないのではないかというか、それとも、品川区としてそういう弾力的運用を認める学校数は年間に何校ですとか決めているとか、そういうことはあるのでしょうか。何でこんなにそういう申請が少ないのか伺いたいというのが１つ。\nそれから中学校なのですけど、裏面にいきますが、これ１年生は区独自の加配措置があるということで、２つ選べるということなのですけど、学級増を選択しないところのほうが５校中３校と、青いところですが多くなっていると。\nこれ、ちょっと安易だなと思っていまして、都としてはやはり、中１プロブレムなどもありますけども、国に先んじて、そういうクラスを少人数加配ということでやっているのに、この３校も加配で済ませているということはどうなのかと。\n例えば大崎中学校だったら、これ本当だったら３クラスなのです。今、２クラスですから３７人と３８人なのですけど、３クラスなら２５人ずつになるということで大違いなのです。先生の負担も重くなりますし、教育環境の向上の点では、これは、保護者の立場としてもクラス分割してほしいと思うのが当然だと思うのですけども、なぜこうした選択になるのか、この選択についてはどういう理由でこういうふうにしているのか、つかんでいらっしゃいますでしょうか。区教委としては何かアドバイスとか助言とかしたりするのか、伺いたいと思います。"},{"i":133,"speaker":"柏木学務課長","text":"まず、弾力化の件ですが、こちらは当然全ての学校が知っています。その上で、学校の実情に応じてですので、学校の実情として細分化の必要がないという判断をしているから申請がないものと考えております。教育委員会で何校までということを決めているということはございません。\nそれと、中学校、７年生のほうの加配の件ですけれども、まず、こちら制度としては、学級増をしてもいいし、加配でチームティーチングできめ細やかな指導もしていい、というふうに選べるようになっていますので、必ずしも学級増をしなければいけないという制度ではございません。ですので、学校のほうが子どもたちの実情等を考えて選択した結果と考えております。細かく選べるからこっちというようなことは直接は聞いてございません。"},{"i":134,"speaker":"安藤委員","text":"学校として、どちらを選択するかというところをなぜ、加配のほうを選んでしまうのかなというふうに、やはり一人一人の子どもというのはもっと先生に話聞いてもらいたいし、先生としてももっときめ細かく見たいわけではないですか。そういうことがある中で、なぜこの３校もこういうふうなことをするのかというのは、正直言うと、保護者からいうと理解できないという方が多いです。私自身もそう思います。\nそれで、伺ったのは、なぜ、この全ての学校でこういうふうな選択をしているかというのは、特に、学級数を増やさなかったところというのは、区教委としてその理由をつかんでいますか、知りたいのですけど、という、それぞれつかんでいたら教えていただきたいと思います。"},{"i":135,"speaker":"柏木学務課長","text":"ちょっと繰り返しになりますけども、学級増をするかしないかというのが学校の実情で選べる制度でございますので、こちらでなぜ増やさないのかというようなことを直接聞いたりとか確認して、そういう認めているとか認めていないとか、そういうことはございませんので、あくまでも学校が実情に応じて判断をしているというものでございます。\nただ、学校の考え方としては、学級増を選ぶところもありますし、加配のところもありますけども、加配のところはある意味、フリーな教員がいて、いろいろ、担任としてではないけれども教科担任とかという関わりの中でいろいろ動けて、子どもたちの相談に乗ったりとか、そういうふうに活用ができると考えているのかなと、こちらとしては考えているところでございます。"},{"i":136,"speaker":"安藤委員","text":"もちろん学校が決めることなので、学校の主体、それが主体というのは分かります。区教委がどうしろとかという性質の問題ではないし、ましてや議会がというものではないのは分かっていますけども、実情に応じてと言いますが、どんな実情があるのかというのが全然分からないということなのです。私は今、議員として話をしていますけども、保護者の立場からすると、何で自分の子どもがもっと緊密な、少人数学級の関係の中で日々の教育を受けられるべきところが受けられないのかなというのは、私はちょっと理解ができないので、保護者が分かるように、そこは少なくとも、どんな実情があるのかというのをきちんとつかんで報告をしていただきたいというふうに思いますので、今後ぜひ、その辺はよろしくお願いしたいというふうに思います。"},{"i":137,"speaker":"つる委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n会議の運営上、暫時休憩いたします。再開は３時２５分です。\n○午後 ３時１０分休憩\n○午後 ３時２５分再開"},{"i":138,"speaker":"つる委員長","text":"休憩前に引き続き、文教委員会を再開いたします。\n────────────────────────────────────────────\n(5) 令和５年度 新入学学校別増減要因一覧について\n次に、(5)令和５年度新入学学校別増減要因一覧についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":139,"speaker":"柏木学務課長","text":"それでは、令和５年度の新入学学校別増減要因一覧についてご報告いたします。\n資料表面が、小学校・義務教育学校（前期課程）の新１年生、裏面が、中学校・義務教育学校（後期課程）の新７年生の増減要因をまとめたものでございます。\n学校ごとに、令和４年１０月１日の住民基本台帳上の通学区域内の児童・生徒数が、実際に４月に入学するまでに、どのような要因で最終的に入学が決まったかということを示しているものになります。なお、一番右にございます入学者数は４月１日現在の人数で作成しておりますので、ご了承ください。\nそれでは、表面、小学校・義務教育学校（前期課程）の新１年生についてです。表の見方でございますが、左の校名の横が、令和４年１０月１日現在のそれぞれの通学区域内の住民登録上の入学予定人数になります。\nその右から、増要因がそれぞれ記載されております。増要因の一番左、学校選択実績（ａ）、こちらは、学校選択でほかの通学区域から希望申請され、実際に入学された児童数になります。希望申請したが入れなかった児童についてはこちらには入ってございません。なお、城南小学校につきましては、就学人口の増加等の理由から、今年度の入学者については希望申請の対象外となっております。\nそのほか、指定校変更、区域外就学、転入等のそれぞれの要因を記載しております。（ａ）から（ｅ）までの合計が、増要因の小計（Ｂ）となります。\n表の右側に、減要因がそれぞれ記載されております。減要因の一番左、学校選択実績（ｆ）、こちらは学校選択でほかの学校を希望申請され、実際に入学された児童数になります。その右の国公立、私立は、それぞれ区立学校以外の学校に入学された人数となります。そのほか、指定校変更、区域外就学、転出等、それぞれの要因を記載しております。（ｆ）から（ｌ）までの合計が、減要因の小計（Ｃ）となっております。こちら、最終的な入学者数が一番右、令和５年４月１日入学者数（Ｄ）となります。\n品川区立学校の合計は表の一番下、昨年１０月１日現在の入学予定人数が３,２９１人、希望申請で入学された方が４３６人、最終的に品川区立学校に入学された方が、表の右の一番下、２,９７８人となります。\n続きまして、裏面、中学校・義務教育学校（後期課程）の新入学でございます。\n表の見方は小学校と基本同じですが、中学校・義務教育学校（後期課程）では、表のほうに、義務教育学校学区外進級数、増要因では（ｂ）、減要因では（ｈ）という項目がございます。義務教育学校は就学期間が９年の学校のため、前期課程に就学されている方は、通学区域外であってもそのまま後期課程に進級することができます。この項目は、前期課程６年生に、通学区域外からの方が何人いるかをまとめたものになります。したがいまして、この部分に関しましては、日野学園から豊葉の杜学園の、こちら（ｂ）が、通学区域外から前期課程に在籍していてそのまま後期課程に進級された方の数。逆に、右側の減要因のほうの、東海中学校から戸越台中学校までの（ｈ）、こちらは各中学校の通学区域から、もともと義務教育学校（前期課程）に在籍し、そのまま義務教育学校（後期課程）に進級された方の数となります。人数としては、それぞれ差引きになりますので、一番下の合計の数が（ｂ）、（ｈ）ともに１７０人となってございます。\n品川区立学校の合計は一番下、昨年１０月１日現在の区内の入学予定人数が２,８０７人、希望申請で入学された方が４０２人、最終的に、品川区立学校に入学された方が、表の一番下の右、１,６７６人になります。\n簡単ではございますが、私からの報告は以上となります。"},{"i":140,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":141,"speaker":"せお委員","text":"ちょっと１点だけ、この指定校変更についてなのですけど、これ、言える範囲でいいのですが、結構私としては数多いなと思ったのですけど、学校別とかではなくてどういった理由があるのかというのを、もしお話しできましたらお聞かせください。"},{"i":142,"speaker":"柏木学務課長","text":"指定校変更の理由は様々ございまして、指定校変更の許可基準というのが５つございます。１つが、指定校への通学が安全の確保の観点から支障がある場合、あと、おおむね１年以内に品川区内での転居が確定していて、その転居先の学校に最初から通っているほうが望ましいと判断される場合、３つ目は保護者の就労の理由によって、登下校のときやむを得ず児童を近親者とかに預けなければいけない場合、これ小学生の場合なのですけれども、４つ目が慢性疾患等で長期的、定期的に通院治療を必要としていて、診療時間の関係で病院の最寄りの学校に通学するのが望ましいと判断される場合、５つ目で、教育委員会が必要と認めた場合、という５つの基準がございます。\nちょっと、細かい数を取っていないのですけれども、感覚的で申し訳ないのですが、多いのは、まずは指定校への通学が、簡単に言うと別の学校のほうが近いとかいう理由の場合です。それと、区内転居が確定している人というのが多いという印象はございます。あとは、本当に個別になるので、そこまでちょっと細かい集計は、現在はございません。"},{"i":143,"speaker":"せお委員","text":"すみません、突然聞いたので。私も以前から、委員会などで要望しているというか、指定校変更の品川区の基準は、今おっしゃったとおり５つあって、それがもう何十年と変わっていないのです。それで、他区を見ると、もう１０何項目、２０項目とかあって、すごく柔軟に対応してくれているところが多いので、ぜひちょっとここの、その５番目の、教育委員会が判断してという項目もあるのですけど、それが判断されるのかどうか保護者にはちょっと分かりづらかったりして、なので、そこの検討などもぜひこれからお願いしたいなと思っています。"},{"i":144,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(6) 令和５年度 感染症による臨時休業措置状況\n(10) 区立幼稚園・保育園におけるインフルエンザ発生状況"},{"i":145,"speaker":"つる委員長","text":"次に、(6)令和５年度感染症による臨時休業措置状況および(10)区立幼稚園・保育園におけるインフルエンザ発生状況についてを関連するものとして、一括して議題に表します。\n本件につきまして、理事者よりご説明願います。"},{"i":146,"speaker":"柏木学務課長","text":"それでは、私のほうから区立学校の令和５年度感染症による臨時休業措置状況についてご報告をいたします。\nインフルエンザなのですけども、報道等にもあってご存じかと思いますが、全国的に、特に学校において集団感染が広まっている状況がございます。区立学校におきましても同様で、特に５月の第３週、こちらのほうからインフルエンザによる学級閉鎖または学年閉鎖が急増してございます。\n資料にございますように、５月８日から６月２日、約１か月間で、延べ２７校、４１学級での臨時休業となってございます。こちらですが、特に地域による隔たりは見られておりません。区内全域の学校で流行している状況でございます。\nこのような状況を受けまして、６月１日に開催されました、校長・園長連絡会において、注意喚起および基本的な感染症対策について周知を行っているところでございます。なお、こちらの資料作成以降ですが、やはりインフルエンザの学級閉鎖等はまだ出ている状況でございます。それと、６月７日に１校、１学級になりますが、新型コロナウイルス感染症による学級閉鎖というのもございましたので、ご報告をさせていただきます。\n以上で、区立学校の状況の報告となります。"},{"i":147,"speaker":"立木保育課長","text":"私からは、区立幼稚園・保育園におけるインフルエンザ発生状況等についてご報告をさせていただきます。資料をご覧ください。\n初めに、幼稚園でございますけれども、お手元の資料では、学級閉鎖した区立幼稚園が１園で、延べクラス１クラスと記載しております。その後、感染者が少し増えまして、６月９日、先週末現在、延べクラス数が２クラスとなりました。幼稚園は、学校保健安全法に基づいて学級閉鎖を行うことができるとされているため、感染拡大防止のために学級閉鎖を実施いたしました。\n次に、保育園ですが、お手元の資料では登園自粛のお願いをした園が１園で、延べクラスは１クラスと記載してございますが、やはり同様に先週末、６月９日現在、２園で延べクラス３クラスということになりました。保育園におきましては、１クラス内で３名以上発症した場合、保護者の皆様に可能な範囲で登園自粛をお願いしております。保育園は就労支援等を目的とする施設のため、原則としてクラス閉鎖は行いません。"},{"i":148,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。\nご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(7) 令和５年度（６年度採用）品川区立学校教育職員採用候補者選考日程について"},{"i":149,"speaker":"つる委員長","text":"次に、(7)令和５年度（６年度採用）品川区立学校教育職員採用候補者選考日程についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":150,"speaker":"中谷指導課長","text":"それでは、私から、令和５年度（６年度採用）品川区立学校教育職員採用候補者選考日程について説明をさせていただきます。\nこちらにつきましては、令和６年４月１日に採用予定の品川区立学校教育職員の採用候補者選考の日程についてのものでございます。\nまず、１、採用予定人数でございますが、５名程度を予定しているところでございます。\n続きまして、２、資格要件でございますが、２つございまして、（１）といたしまして、小学校教諭普通免許状および中学校教諭普通免許状（教科不問）の両方を所持する者と、（２）といたしまして、小学校教諭普通免許状および特別支援学校教諭普通免許状の両方を所持する者、この２つのいずれかに該当する者とさせていただいております。\n続きまして、３の選考区分でございますが、昭和３８年４月２日以降に出生した者となります。昨年度まで、選考区分を一般選考と経験者選考に分けまして、それぞれにつきまして年齢制限を設けておりましたが、これらを撤廃することで、より多くの方に応募いただけるように変更をしております。\n４の選考日程でございますが、募集期間としまして令和５年４月２４日から６月２８日までを予定してございます。その後、第１次選考は令和５年７月２２日土曜日、結果発表を経まして、第２次選考は令和５年９月２日土曜日、最終の採用面接につきましては令和５年９月２３日土曜日を予定しております。\n説明については以上でございます。よろしくお願いいたします。"},{"i":151,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":152,"speaker":"安藤委員","text":"昨年が４名程度採用をして、３０名を目指して採用したという報告が昨年もあったのですが、今回５名採用ということなのですが、これは３０名の目標を超えて採用するということなのでしょうか。それとも、やはり途中で退職されたりという方がいらっしゃった、あるいは４名の採用ができなかったということなのか、伺いたいと思います。"},{"i":153,"speaker":"中谷指導課長","text":"人数についてのお尋ねをいただきました。定員が３０名というところにつきましては、昨年度も今年度も同様の数を目指しているというものになります。今年度４月１日で２名の固有教員を採用させていただいております。前年度末に退職者が３名おりました。したがいまして、現在、在籍者数が２５名というところになっておりまして、今回、５名程度を採用させていただくという流れで進めさせていただいております。"},{"i":154,"speaker":"安藤委員","text":"やはり、今なかなか、学校教員をめぐる環境は厳しいということで、別に区の採用に限らないのですけど、途中でやはり辞めざるを得ないという方も出てくる深刻な状況だと思います。採用を進めるのは結構なのですけども、やはり今は学校で働く教員の皆さんが長く続けられるような、そういった待遇面もそうですし、あとは働き方改革という点でも頑張っていただきたいなと思います。"},{"i":155,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":156,"speaker":"高橋（し）委員","text":"独自採用の先生方は一生懸命仕事をされて、学校の貴重な戦力になっているとお聞きしています。先ほどもあったように、副校長先生に区の独自の方を３名配置しているというのも、大変すばらしいことだと思っています。それで、その次の段階として、区のほうの努力で、教育委員会の努力で、管理職に区独自の先生がなれる道筋をつくっていただいたのですけど、その次、つまり、校長先生、そこへの流れというか、現状、どのような、区として働きかけていく、東京都の考え方とか、あるいは法律との関係もあるのですが、その点の展望についていかがでしょうか。"},{"i":157,"speaker":"中谷指導課長","text":"管理職になってから、その後のロードマップというところでご質問いただきました。今、先ほどお話させていただいた３人の副校長につきましては、５級職ということで、東京都と同じような副校長という立場の方でございます。この方々が行く行く、次なる職を、同じく管理職ですけれども、次の６級職を目指していただくべく、教育委員会といたしましては昨年度から統括副校長という職を設けさせていただいております。つまり、現在副校長になられた方が、さらにスキルをつけていただきまして、マネジメント力をつけて、挑戦していただく最高職の管理職というところで、現在、昨年も含めまして、選考をやらせていただいております。こちらのほうに、今一番候補となる方々が副校長先生でもいらっしゃいますので、こちらのほうに選考を受けていただくというところで進めていきまして、やがてはこちらの職になって、また、さらに品川区で活躍していただける管理職の先生を輩出していきたいというふうに考えております。"},{"i":158,"speaker":"高橋（し）委員","text":"統括副校長先生になっていただくような選考ということで、すみません、私、分からないのですが、校長先生というランクの仕事というか職名との関係はどういうことになるのか、ちょっと分からないので。"},{"i":159,"speaker":"中谷指導課長","text":"これまで、この校長という役職名をつけたいというところもありまして、東京都教育委員会のほうとの調整が非常に必要な案件でございまして、かなり、粘り強く、まずその６級職イコール校長というところで交渉をずっとやっておったのですけども、最終的には、結論として先ほど申し上げた統括副校長という名称であればよいということと、給与について、東京都の校長職と同じ給与を保障できるというところまでの結論になりまして、ゆえに、こちらの役職を創設したという経緯でございます。"},{"i":160,"speaker":"高橋（し）委員","text":"分かりました。ありがとうございました。それの仕組みがうまく整って、ちょっと時間をかけて、名称として校長というふうにできるようになるといいのですけど、ある学校の校長先生という名称の方はいなくて、統括副校長先生がいるということになるのですか。"},{"i":161,"speaker":"中谷指導課長","text":"役職名が校長ではないので、この方が仮に配置された場合に、学校の校長というところでの配置はできないというところがございます。ただ、この固有の先生の最高職であるこの６級職の方々に品川区として何を目指すかという議論を重ねてきまして、やはり、長らく根づいて活躍されていらっしゃる品川の先生が、品川の教育施策を強力に推進していく最高トップになっていただきたいという意味においては、エリアの中での統括マネージャーのような役割、つまりは、例えば一つのある学校に統括副校長として赴任していただいた場合には、その学校のマネジメントだけではなく、そのエリアの近隣の学校への影響力というところも含めたマネジメントをしていただきたいというような絵図を描いて、目指しているところでございます。"},{"i":162,"speaker":"高橋（し）委員","text":"いろいろありがとうございます。都との調整をしていただいて、そこまでのところまで来ているということですので、今後も期待するということで、東京都のほうの統括校長先生の仕組みというのに近いと言ったらあれですけど、そういうことを想定しているのだなと思います。今後も、都との調整はあれですけど、独自教員の先生方のキャリアの目標になるような仕組みが整備されていることを期待します。"},{"i":163,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(8) 令和２年に区立学校で発生したいじめの重大事態への対応について"},{"i":164,"speaker":"つる委員長","text":"次に、(8)令和２年に区立学校で発生したいじめの重大事態への対応についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":165,"speaker":"米田教育次長","text":"本日報告をさせていただきますいじめの重大事態へ対応についてですが、初めに、被害生徒の方やご家族に大変なご心労をおかけしていること、重大事態としての認定が遅れましたこと、法に基づく区長報告ができておりませんでしたことにつきまして、おわびを申し上げます。誠に申し訳ございません。\n今後はこのようなことがなきよう、いじめは許されないという意識の向上や、組織的対応の見直し、法令等理解の徹底に努めてまいります。\n内容につきましては、教育総合支援センター長より報告をさせていただきます。よろしくお願いいたします。"},{"i":166,"speaker":"丸谷教育総合支援センター長","text":"それでは、私から、令和２年に区立学校で発生したいじめの重大事態への対応について、ご報告をいたします。\n資料ですけれども、右上に文教委員会資料と記されたもののほかに、右上に（別紙）と書かれている、Ａ４判表裏のもの、もう一つ、（別添）と右上に書かれている、左側２か所ステープラーどめになっているもの３点がございます。説明の中で、資料をまたがって説明となりますけれども、ご了承いただければと思います。\nでは、令和２年に区立学校で発生したいじめの重大事態への対応についてと書かれている資料をご覧ください。\n初めに、１、事案概要についてでございます。令和２年に区立中学校生徒１名に対して、何者かによって学用品の損壊や、机の中に「しね」などと書かれた紙片の投入等が繰り返しあり、被害生徒は学校生活に不安を覚え適応障害と診断されました。\n学校では被害生徒の訴えの後、直ちにこれをいじめと認知するとともに教育委員会に報告し、警察とも協力しながら、いじめ行為の停止に向け、生徒への指導や調査を行うなどの対応を行ってまいりましたが、いじめを解消することができず、当該生徒は他区の中学校への転校を余儀なくされました。\n区教育委員会は、本件について令和４年３月に被害生徒の保護者からいじめの重大事態に当たるのではないかとお申出をいただき、いじめ防止対策推進法第２８条に基づくいじめの重大事態として、品川区いじめ対策委員会を立ち上げ、令和５年３月まで調査を行いました。\n同委員会による調査結果では、学校・教育委員会のそれぞれの対応について不適切・不十分な点があったこと、および、被害生徒が適応障害の診断を受けたなどの時点でいじめの重大事態として調査・報告すべきであったことなどのご指摘をいただきました。\nまた、本件に関する教育委員会から区長への報告は、いじめ防止対策推進法の規定により、本来であればいじめの重大事態発生時に行うべきでしたが、いじめ対策委員会による調査終了後の本年４月まで行っておりませんでした。\n本日、別添資料として調査結果をご用意しております。恐れ入りますが、調査結果の資料をご用意いただけますでしょうか。調査結果の項目のみ説明させていただきます。\n表紙をおめくりいただきまして、１、はじめに、２、被害生徒について、３、調査の概要を示してございます。４、調査結果として、（１）いじめの内容と当該校の対応、こちらが６ページまで続いております。（２）いじめ行為と転出の関連性について、（３）転出後の対応については７ページに続いております。\n７ページの下のほう、（４）当該校の対応の課題、こちらは９ページまで続いておりまして、９ページの下のほうですが、（５）区教育委員会の対応の課題、こちらが１０ページまで続いております。\n最後に、５、再発防止に向けた提言として、次の１１ページにかけて、こちら（１）から（５）の５点いただいております。以上が調査結果となっております。\nこの調査結果を受けまして、今後の教育委員会における対応について検討をいたしました。初めの資料にお戻りいただけますでしょうか。\n資料の中段、今後の対応・スケジュールの（１）教育委員会における対応についてでございます。大きく３点ございます。第１に、ア、「いじめはどんな理由があっても許されない」という意識の向上、第２に、イ、組織的対応の見直し、第３に、ウ、教育委員会事務局内での法令・制度の理解の徹底でございます。\n詳細を別紙に用意してございます。恐れ入りますが別紙をご覧いただけますでしょうか。ポイントを絞って説明をいたします。\n別紙の１、「いじめは絶対に許さない」という意識の徹底では、（２）品川区いじめ防止対策推進基本方針の見直しと改訂を行います。特に「重大事態の対処」の項を充実させ、具体的な対応策について記述を加えてまいります。（３）教職員に対する研修では、2)の校長・副校長研修等、職責や経験等に応じた研修の機会を捉え、法や条例等の理解の徹底、対応技能、連携力の向上を図ります。（４）児童・生徒等に対する「いじめはどんな理由があっても許されない」という指導の徹底では、1)のいじめ予防プログラムを活用した授業実践の充実を図ります。\n第２の組織的対応の見直しについてです。（１）学校における対応の強化についてですが、いじめに対処するのは学校であることから、1)にあるとおり、校長の強いリーダーシップが必要不可欠と考えております。2)の学校いじめ対策委員会の定期開催や、3)の対策委員会による即時対応、教育委員会事務局への報告・協議。また、4)、5)にありますとおり、関係機関と連携を図りながら対処に当たります。\n続きまして、（３）の教育委員会事務局内の体制・情報共有方法の構築についてですが、特に重大性の大きいいじめ事案については、教育委員会事務局内で情報共有を行い、対処方針を確認しながら対応してまいります。\n第３の教育委員会事務局内での法令・制度の理解の徹底についてです。（１）国が示しているいじめの重大事態の調査に関するガイドラインの理解を徹底し、いじめ事案が重大事態に該当するかの手順を策定してまいります。これは今後、事例を積み重ねていき、具体的な基準を策定していくものでございます。（２）区長部局への連絡・報告方法の構築についてですが、学校または教育委員会がいじめの重大事態と認知した場合には、速やかに区長部局に連絡・報告するほか、事務手続に漏れのないよう確認方法を確立していくものでございます。\n初めの資料に戻っていただきまして、裏面をご覧いただけますでしょうか。\n（２）に、区長部局における対応の記載がございます。こちらは参考として記載してございます。区長部局にいじめ問題調査委員会を設置し、本件に関する調査が実施されることとなっております。\n最後に、資料の下段の３、その他についてでございます。今回の事案とは別に、令和５年５月に区立中学校において発生したいじめ事案について、いじめ防止対策推進法第２８条に基づくいじめの重大事態に当たるものとして、令和５年６月２日付で教育長から区長に報告を行いました。今後、区教育委員会といたしましては、品川区いじめ対策委員会を立ち上げ、本事案に関する調査を実施いたします。調査結果が上がってまいりましたら、区長および議会への報告を行ってまいります。\n説明は以上です。よろしくお願いいたします。"},{"i":167,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":168,"speaker":"安藤委員","text":"本当に大変重大な問題だなと。苦しんだ被害者の方もそうですし、同時に、いじめをした児童・生徒というのがまだ誰か分かっていないみたいですけども、自分たちがした行為について、当然、反省もできていないし、振り返りもできていないという中で、もう既に当該の学年の方は高校に進学しているわけですから、そういった意味で二重の意味で本当に、今後のことを考えると、今回の重大事態というのは、本当に氷山の一角だと思うのですけども、真摯に受け止めて、今後につなげていかなくてはいけないなと強く思います。\n今回、いじめの重大事態の発生ということなのですけども、本区では、２０１２年の痛ましい、いじめによる自殺も起こっておりますが、その後このいじめの重大事態ということは発生していなかったという認識でいいのか。新たに、今年の５月にも重大事態だという報告があったということなのですけれども、こちらはどういうような事態なのか、これを簡単に教えていただきたいです。\nあと、いじめ対策ということで、曲がりなりにも、方針もつくって、条例もつくって、基本方針も立てて、バッジも配って、いじめの発生を防ごうとしてきたと思うのですけども、今まで、アンケートですとか調査なども行っていたように思うのですが、そういった調査では、アンケートなどでは、今回の令和２年度の事態等は報告がなかったということなのか、教えてください。"},{"i":169,"speaker":"丸谷教育総合支援センター長","text":"何点かご質問いただいていますけれども、まず、いじめの重大事態が発生していなかったかという点につきましては、平成２４年度に大変痛ましい事故があってから、法律が定められまして、今回、いじめの重大事態として調査したものは今回が初めてであるということになります。\nまた、新たに、令和５年５月、今年の５月に起こったいじめを重大事態として認定したということですけれども、今後、調査が行われますので詳細は控えさせていただきますが、法に基づいて対応しているというところでございます。\nまた、いじめ対策として条例や基本方針、いじめ防止バッジを配布して子どもたちのいじめ防止、いじめ予防の啓発活動を行っております。また、定期的にアンケートも行っておりまして、いじめの早期発見には役立てているところですけれども、今回のいじめの重大事態については、いじめの認知については素早く行って、対応は行ってきているものでございます。アンケートで発見したものではなくて、当該生徒が先生に報告をして、学校が対応していった案件でございます。"},{"i":170,"speaker":"安藤委員","text":"何というか、これだけ重大な事態があったのですが、ちょっとアンケート等は特に、それが重大事態を防ぐことにはつながっていなかったということなのでしょう。\nあと、いじめの重大事態という定義について、改めて区教委のいじめの重大事態とは何なのかと考えているかというのを教えてください。\nそれと、区長部局で、条例に基づいて新たな第三者機関が立ち上がって、その先に必要な措置ということで示されているのは、今後区長部局にその検証を行った後、いじめ問題調査委員会を立ち上げて検証を行った後に、いじめの専門部署の構築をするなどの対策を早急に検討するというふうに区長からの考えが示されているのです。これはちょっと今資料ないのですけど、そういうふうに聞いています。そういう資料もいただきました。この区教委としては、区長部局にいじめの専門部署の構築をするということについては、どのように認識して評価しているのか伺いたいと思います。"},{"i":171,"speaker":"丸谷教育総合支援センター長","text":"それでは、まず、いじめの重大事態の定義でございますけれども、いじめ防止対策推進法の第２８条に記載がございまして、こちらは品川区でも同様のものとなっております。\n申し上げますと、２点ございまして、１点目は、いじめにより当該学校に在籍する児童等の生命、心身または財産に重大な被害が生じた疑いがあると認めるとき、もう１点は、いじめにより当該学校に在籍する児童等が、相当の期間学校を欠席することを余儀なくされている疑いがあると認めるとき、この２点でございます。\n今回、報告いたしましたいじめの重大事態は、この１点目の、当該学校に在籍する生徒の心身の部分に重大な被害が生じた疑いがあるということで、重大事態に該当するというふうなことで調査に当たったものでございます。\nまた、２点目の、区長部局に専門部署を設けるということについてですけれども、一番守るべきは、学校に通っている児童・生徒の安心安全ということだと考えております。対応する部署が、教育委員会だけではなくて区長部局にも設けられるということは、相談窓口が増えるということ、対応窓口が増えるということで、こちらとしては児童・生徒のためになるものというふうに考えております。"},{"i":172,"speaker":"安藤委員","text":"分かりました。ちょっと今後の対応、区教委の対応のところを見ますと、これを読みましたけども、これ自体は必要ではないとは言いませんし、必要なことだと思うのですけども、アとイとウですか。ただ、いじめを解決するというよりは、やはり、最終的にはいじめをやった、いじめをしている子どもというのがいじめをしなくなるという必要があると思うのです。いじめ根絶というと、もう何か勇ましいのですけど、なかなか実態というのは難しいというか、今回のような本当に大変ないじめもあれば、その成長の、何というか、いじめを根絶というのはなかなか難しい面があります。もちろん目指すべきです。なのですけど、ではいじめはどうしたらなくなるのかというと、やはりいじめをされて、その生命を守るというのは第一義ですし、そこに寄り添うということが一番大事なことなのですけど、同時に、いじめをする子どもが、自分がしたいじめをずっと、今回犯人も見つからなかったということもありますけど、見つかろうが見つからまいが、このいじめをしようと思わなくなる必要があるわけです。では、いじめをしないという児童・生徒をどう育てるのかと、こういう視点が、この区長の対応には欠けているなと私は思います。いじめをしている子がいじめをしなくなるには何が必要なのか、この視点というのを対策の一番に入れるべきだと私は思うのですけども、いかがでしょうか。"},{"i":173,"speaker":"丸谷教育総合支援センター長","text":"いじめを行った者がいじめをしなくなるような取組が大切というようなご質問だったと思います。そのとおりだと思いまして、いじめはどんな理由があっても許されないという意識の向上というところに含まれると考えておりまして、まず、児童・生徒が、いじめの定義、いじめとはどういうものなのかというのを理解した上で、もしいじめ行為を行ってしまったら、あなたがやったことはいじめに値するんだよと、そうならないためにはどう生活すればいいかということを反省したり促したりしながら、今後の、いわゆる加害と呼ばれる児童・生徒がいじめを繰り返さないような対応ということが必要だと考えております。"},{"i":174,"speaker":"安藤委員","text":"それで、このアの部分だと思うのです。「いじめはどんな理由があっても許されない」という意識の向上が必要だというのは、本当にそうだと思うのですけども、ではここに書いているような、この「いじめ根絶宣言」というものの理解を徹底するというようなことをすれば、いじめをしていた子どもはいじめをしなくなるのかと、私はそういうものかなとは思えないのです。\nこの「いじめ根絶宣言」というのをいただきましたけども、「いじめは、どんな理由があっても決してしてはならない。」「いじめは、どんな状況にあっても見すごしてはならない。」「全ての区民参加で、いじめは絶対に許さない社会をつくりあげる。」と。\n「いじめは、どんな理由があっても決してしてはならない。」というこのいじめの禁止事項ですけど、いじめが犯罪だとか、あるいは人権侵害だと、やってはいけないのですよということを、では子どもは理解していないのか。残酷な事実なのですけども、やはりいじめをしている子どもというのは、このいじめ、駄目なことというのはよく分かっていると思います。それだけにいじめをやめるようにするには、こういうこの宣言とかで、いじめは駄目ですよ、と幾ら繰り返しても、いじめをやっている子どもがいじめをやらないようになるとは思えないのですけども、この点、なぜいじめ根絶宣言の決定が、子どもがいじめをしなくなることにつながるのか、そうなるのか、認識を伺いたいと思います。"},{"i":175,"speaker":"丸谷教育総合支援センター長","text":"いじめ根絶宣言は、平成２５年に区教育委員会が宣言したものでございます。この宣言を基に、各学校独自にいじめ根絶宣言というものを児童・生徒会を中心に考えておりまして、そういった取組をいま一度、また新たに充実させていくことで、教員だけではなくて、子どもたち自身も、いじめは駄目なのだというようなことの意識を向上させる取組が必要と考えております。"},{"i":176,"speaker":"安藤委員","text":"やはり、私が言ったのは、そのいじめを幾ら、理屈抜きに禁止、駄目だといっても、それは重々分かられているので、なぜいじめが駄目なのか、いじめがどのような事態をもたらすのかというのを、やはり、いじめをする子どもに考えてもらうというか、そういうことがすごく必要なのではないかと。これはまだ、中身は理解したかもしれませんが、こういう事態を何回も繰り返して徹底しても、いじめはなくならないのではないかなというふうに思っています。\nちょっと、最後、この報告書を見たのですけど、ここでこれ見て思ったのです、繰り返し繰り返し、説諭という言葉が出てきます。これは正しいと。教え諭すという意味だと思うのですけども、子どもに対して、いじめは駄目なのですよと、全校集会やクラスでも何回も何回も行われていました。ではそれでいじめがなくなったのかというと、むしろ逆だったのです。そもそも、もっと、どうやったら大人に見つからないようにいじめをするかということを、エスカレートもしているし、繰り返し繰り返し、やめるどころかむしろエスカレートしているというようなことを、この報告書の中だけからでも読み取れると思うのです。ですから私、言っているのです。\nこの伺いたいのは、この説諭というのは一体これ、実際何が行われているのか。この宣言も持っていました、方針も持っていました、条例もありました。その中で恐らく、ある程度そういうのに基づいて、現場の方はやったのかもしれないのですけど、そのいじめをしている子どもたちに対して、どのようなお話をしたのか、説諭をしたのか。その説諭というのをもう少し中身を伺いたいですし、そして、ここにあまり書かれていないのはなぜなのか、併せて伺いたいと思います。"},{"i":177,"speaker":"丸谷教育総合支援センター長","text":"学校が行った説諭の内容についてですけれども、いじめの行為が行われた際に、体育館等に学年全体を集めまして、やられたほうの気持ちを考え、加害者が今回見つかっておりませんので名のり出てほしいということや、今後そういう不安な中での学校生活は、子どもたちも先生たちも送りたくないというようなことで、全体指導、当たっているものでございます。\n今、そうは言ってもいじめはなかなかなくならないということですので、今回、この別紙の１の（４）に記載をしてございますけれども、いじめの事案発生予防教育のさらなる工夫ということで、東京都がいじめ総合対策実践プログラム編等用意してございます。こういったいじめ予防プログラムを改めて学校に周知しながら、実施の徹底を図っていきたいというふうに考えているところでございます。"},{"i":178,"speaker":"安藤委員","text":"私が伺ったのは、その説諭の中身と今、センター長のほうから言われましたけど、そういう、この報告書を見ますと、犯人探し、監視という、あるいは物理的に、そういういじめができないように、メモを入れられないように机の棚を外すみたいなそういうこと、あと監視カメラの設置の議論とかありますけども、そういうことばかり書いていて、では実際にその説諭の中身というのは、教育的にどのような働きかけが行われていたのかというのはちょっと見えない報告書だなと思っているのです。\n今ちょっとご紹介ありましたけども、その辺がここに書いてないというのはなぜなのか、伺いたいというのを伺ったので、聞かせていただきたいですし、もう少し、そういった内容がほかにもありましたら教えていただきたいと思います。"},{"i":179,"speaker":"丸谷教育総合支援センター長","text":"今、ご案内のありました物理的な対策や、監視カメラの設置というような議論につきましては、警察とも連携を進める中で出てきた方策の一つでございます。子どもたちへの教育的な視点で学校は対応してきましたので、できることならば、物理的な対応、対策、机の棚を外すとか、そういうことはしたくなかったのですけれども、加害の行為が止まらないということで、やむなく実施したという経緯もございます。そういった意味で、説諭を繰り返し行うということで、教育的な心に訴えかけるという指導を学校としては繰り返し行ってきたということでございます。"},{"i":180,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":181,"speaker":"石田（し）委員","text":"今回の件に関しても、全体的に様々、その報告等が遅れてしまったというのが、一つこの問題を大きくされているのかなと思うので、この点などに関しては、今、お話があったようなことをしっかりと徹底してやっていただきたいと思います。\nただ、先ほど安藤委員がとてもいいことを幾つかいろいろ言っていて、私も珍しく「おっ」と思ったのですが、本当に、なくすと簡単に言うけど、僕は正直なくならないと思うし、これはもう人間社会においてなかなかなくならない。だけど、減らすことはできるのではないかと。その作業をどんどんやらないといけないと思っていて、確かにこういった、そもそもの理念だったり、対策チームをつくるというのはもちろん、それはやらなければいけないことですが、こればっかりをやっていても何の解決にもならない。\n現に、品川のみならず全国各地で様々ないじめ問題が発生してしまっているので、特にそれが重大化されている今の現状で、ではどのように解決していくかというと、大きく、まず早い段階で解決をする。結局、長引けば長引くほど、その当該生徒の精神状態というのはどんどん追い詰められるわけでありますし、加害生徒たちも隠蔽工作を取ってしまうといった中では、やはり早い段階で何とか見つけて、その解決をすると。そのためにやはり、全校生徒を体育館に集めて、こうして、いじめは駄目ですよと言ったって、それは子どもはいじめなのか遊びなのかも分からない中でやっている可能性もある中で、それは難しい。もちろんそれも必要なのだけど、やはり、本気で大人が、いじめは許さないのだという意思表示をしっかり示すということが大事だと思う。\nある学校の先生に、関係者の方に聞いたら、その先生は、もう一番初めのときに、もう絶対に僕はいじめを許さないと。先生はそれはもうはっきり一番初め言うと。しかも強く。この本気を大人が示すことによって、子どもたちもそこにその熱伝導で伝わることがある。実際に、そのクラスの子はいじめをやらない、という、それはどこまで、それは見えていないのか分からないけど、僕はそう聞いたのです。それは確かにやはり、この本気度を示すというのは大事だと思っているので、こういったその実効性のある対策をどんどん、品川区としても取っていただきたいと思う。\nもちろん、そのいじめ対策のチームを設置するだとか、理念をしっかりとつくって、みんなでいじめをなくそうと、それはもちろんいいのだけど、それだけではなくてやはり実効性のある施策をどんどん打っていっていただきたいなというふうに思うので、それはやはり生徒に対し先生が本気で許さないんだという姿勢を見せるというのが第一、でももちろん早い段階で解決をしていく。そこを解決するためには、やはり生徒とのコミュニケーションがどうしても必要だと。それはやはり現場の先生なのです。教育委員会でもないし、誰でもなくて、やはり担任の先生だったり、各教科の、ここでは出ていますけど、音楽の先生が一番初めだったのかなと思うのですけど、そういった、その生徒と接している、一番近い現場の先生、そこを、先生とのコミュニケーションはしっかりと学校内、もしくは教育委員会でもやはり図っていくべきだし、生徒とのコミュニケーションというのを充実していかなければいけないのではないかなと。やはり先生は見ているので分かるし、ということはやはりその生徒も、近い先生だったらその距離感で相談もしやすくなる。逆に、近過ぎてできないときもあるけど、やはりそこは友好的にできるのではないかなと、やはりそこはコミュニケーションしっかり取っていく。\nさらには、先ほど本気度と言いましたけど、やはり子どもは、いわゆる学校よりも、親のほうが怖いわけです。やはり保護者に対して、もしこういう事案が出たときには、保護者にもその子どもと向き合ってもらって、実際、学校でどういうことが起きているのかというのを生徒と話し合ってもらう。これは結構重要で、やはり、それはその親にだからこそ話せることがあるわけです。「実は誰々君がこういうことをクラスでしていたんだよ」みたいな。それを、ヒアリングをしっかり受ければ、そういう今まで見えなかったことも見えてくるし、学校内で幾ら「みんなどうなんだ」と言ったって、そこで出てこないものも、保護者を通したら出てくることはいっぱいある。そこはやはり実効的にそういった取組もしてほしい。\n究極を言えばやはり警察介入が大事になってくるのかなと思う。これも、重大になったときではなくて、ある一定の早い時期に警察官も含めた連携を取るべきではないかと思う、そろそろ。やはりそのぐらい本気でやらないとこれは解決にならないと思うのです。なので、そこはぜひ、実効的な、そして現実的な施策をどんどん打っていって、本気で、大人がやはり子ども社会に対しても、いじめは許さないのだというのを強い意志を持ってやらなければ、大人の社会で幾らそれを見せていたって、何も子どもたちには届いてないと思います。それは自分たちもそうだったし、体育館で全校生徒が集まって、校長先生がいじめは駄目だと話したって、ではそこで、みんな分かった、やめようとなると思いますか。これなのです。\nやはりこれを真剣に考えていかないと、本当に減ることはない。減らすためにはやはり本気で取り組むしかないので、それは先生にもご苦労かけるかもしれないけれど、そのぐらい本気でその生徒と向き合ってやっていくことによって、その解決というのは十分できるのではないかなと思うし、それは様々なコミュニケーションを取る必要があると思う。それは保護者だったり、もちろん教育委員会の皆さんだったり、警察、最後やはり警察というのは大きいと僕は思う。子どもにとってもやはり警察官とは特別な存在なのです。親もそうだし。学校の先生もそうだった。\nだけど、今、現状、学校の先生に対しては、いろいろその懲罰の話もあるけど、なかなか本気で怒ることができているのかと、やはり今の時代なかなか難しくなってきてしまっているのかなと。そんな中で、親だったり、警察を巻き込んで考えていかなければいけない時期に来てしまったのかなと思うので、教育委員会としてもそこは大きく政策判断をしていただいて、もちろん、学校に警察が入るというのはやはり異様な風景だと僕は思うのですけど、その異様な風景を生徒たちが見ることによって抑止力にもなってくる可能性も十分あるし、そのぐらい本当に、本気で解決をしていくという姿勢を教育委員会が、そろそろ実効的なものを見せてほしいというふうに思うし、それをやらなければ本当、解決にならないと思うので、ぜひその辺をやっていただきたいと思います。\nそれに関して、ぜひ、何かコメントがあれば言っていただければと思います。"},{"i":182,"speaker":"丸谷教育総合支援センター長","text":"何点かご指摘いただきましてありがとうございます。\nまず、報告の遅れにつきましては大変申し訳なかったと考えておりまして、今後こういうことのないように内部の体制を構築してまいります。\nまた、いじめはなかなかなくならないということで、これもまさにそのとおりだと思っています。小さないじめはたくさん起こります。それを一つ一つ教員の目で見て、学校いじめ対策委員会で認知をして、早期解決に向けた早期対応を行っていくことが何より大事だと考えておりますので、そうしたことも今、研修の中で、校長先生、生活指導主任のほうには既に伝えているところでございます。\nまた、やはり教員が子どもに対して真剣に向き合うという意味では、そうした学級風土であるとか、その特定の学級だけではなくて学校全体がそういう風土を持つ必要があると思いますので、そうしたいじめ予防プログラム等を活用しながら、進めていきたいというふうにも考えております。\nまた、相談体制についても、声をかけやすい先生に相談できるようにということで、そういった働きかけも学校にはしてまいります。\nまた、保護者の理解というのも必要だと感じていまして、ここが今、学校でも課題として感じている部分であります。ですので、教育委員会としても、保護者にどういうふうに働きかけを行えばいいか、保護者、地域も含めて、いじめに対応できるかということは今後、課題というか検討して進めていきたいと思っています。\nまた、警察を含めた関係機関とも連携しながら、いじめについては対応していく必要ございますので、そちらも併せて行ってまいります。ありがとうございました。"},{"i":183,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":184,"speaker":"せお委員","text":"ちょっと何点か。今、いろいろお話、質疑あって、ここに書かれている対策などはもう本当に、もちろんやっていただきたい。それに加えて、加害者のご家族というか家庭環境とか、そういったところにちょっと問題があるというか、何か支援をしていかなければいけないという場合が多いという話も聞いたことがあります。そういったところへの、今後、調査委員会設置して対応策などはここで考えていくとは思うのですけど、もちろん被害者への寄り添いというのはここにも書かれていますので、それは必要で、でも加害者のほうの、もう二度とやらないように、あとは、今後そういった同じような環境の方たちがこういういじめに加わらないようにするために、ちょっとご家族への支援みたいなところはどういうふうに考えているのか、ちょっとお聞かせいただきたい。\nあと、先ほど、状況に応じた映像機器等の活用とあるのですけど、一時的なものだったら活用はありかなとは私は思っているのです。ただ、やはり学校の判断に任せたりとか、そういったことだと判断が難しいと思いますので、設置基準とかそういったことも入ってくるのかを教えてください。\nあと３点目、最後に、ＨＥＡＲＴＳなのですけど、以前は、ＨＥＡＲＴＳ全員、会計年度任用職員だったというお話を聞いていますけども、今どういう状況になっているのか教えてください。"},{"i":185,"speaker":"丸谷教育総合支援センター長","text":"加害者への支援ということですけれども、今回は残念ながら、なかなか加害者を特定できない難しい案件でございました。一般的ないじめの事案になりますが、加害行為を行った児童・生徒の家庭にも何らかのというような場合があるということですけれども、そういったことが分かりましたら、学校・教育委員会だけではなくて関係機関とも連携をしながら、必要な支援の方法を探していくというふうに考えております。\nまた、映像機器の活用についてですけれども、これは単に学校だけではなくて、教育委員会の判断や、また、家庭の理解、地域の理解等々も必要になってくると思いますので、その事案、事案によって変わってくるものかなというふうにも考えております。必要に応じて、関係の各所と協議をしながら、活用については、検討していきたいと考えております。\nまた、ＨＥＡＲＴＳのメンバーについてですけれども、スクールソーシャルワーカー、教育心理相談員含めて、会計年度任用職員がほとんどといいますか、今、１人正規の職員で教育心理相談員の配置がありますけれども、基本的には、会計年度任用職員でつくられている組織になってございます。"},{"i":186,"speaker":"せお委員","text":"ＨＥＡＲＴＳに関しては、もちろん、会計年度が多いからといって成り立たないとは思わないですけど、でも、一応１年契約とかで皆さんがやっている中で、ＨＥＡＲＴＳという中での連携は取れるのかなというのは疑問に思うことがあって、もちろんＨＥＡＲＴＳを強化していくことが全てではないのですけど、一つの支援としてＨＥＡＲＴＳはすばらしい、皆さん助けられている機関ですので、そういったところのもうちょっと、ＨＥＡＲＴＳの中で連携が取れるような体制づくりはお願いしたいなと思っています。\nそのほかのところは理解いたしました。ありがとうございます。"},{"i":187,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":188,"speaker":"高橋（伸）委員","text":"この報告書、調査結果を読ませていただいていました。この管理職と教員間との引継ぎのところなのですけど、校長先生と生活指導主任が異動されたと。引継ぎはきちんとなされていたのだけども、十分には適切に行われていなかった。ここは非常に重要なところだと思うのです。当然これ、学校任せにしてはいけない問題とは思うのですけども、赴任してきた校長、主任がどこまで引継ぎを受けて、どこまで本当に認識しているのかというのは、すごくこれ、今後に向けても重要な課題だと思うのです。そこをきちんとこれは、今後もきちんと精査していただかないと、また、同じような、大小の中で、これに関しては、いじめというのはもう絶対あっては、根絶というのはもう絶対基本なのですけども、これは小さいこと大きいこと、やはり今後ももしかしたらあるかも、多分あると思います。その中でもやはりここは、当該生徒もその主任にはすごく頼っていたと。その先生が異動されたというのは、これはもう、職員の方たちの異動というのは当然あることだから、その後の対応です。そこをやはりきちんとやっていかないと、それは当該学校の知恵を通してやっていかないと、これはもう、また今後起こり得る課題だと思うので、そこはきちんと今後、校長含めて教職員の方々も、校長会などにも、そこは認識をしていただいているとは思うのですけども、そこはきちんとやっていただかないと駄目だと思います。\nそれと、先ほど石田しんご委員からも警察という言葉が出てきました。私もそれは重要なことだと思うのです。ただ、その前に、げた箱の入り口とかに防犯カメラを設置するとか、もうしていくしかないのかなと。それが一番、防犯カメラというのは監視するのだったらもう絶対それは必要なことだと私は思っているので、ぜひ、今後そういうふうに含めて、やっていただきたい。\nそれとあと地域です。地域によっても、品川区も当然地域性があると思いますけども、地域とＰＴＡ含めて、もう本当、協議体をつくって深掘りをしていただきたいと思います。\n私からはあれなのですが、もし何かあったらご答弁お願いしたいと思います。"},{"i":189,"speaker":"丸谷教育総合支援センター長","text":"まず、引継ぎの件につきましては、今回管理職と生活指導主任が２人とも替わったというケースでございました。やはり学校としては、組織的な対応ということが大切かというふうに考えておりまして、この引継ぎ事項、特に学年が上がるときとか、例えば小学校から中学校に校種がまたがるような事案も含めまして、引継ぎはしっかり行っていくということで周知徹底を図ってまいります。\nまた、防犯カメラの件ですけれども、当該校につきましては、外からの侵入者を見張る防犯カメラはついていたのですが、げた箱の所についていなかったということで、今回この答申を受けまして、設置の工事を行いました。げた箱には防犯カメラがついたということでございます。\nまた、地域についてですけれども、今回、校区教育協働委員会には大変協力していただきまして、何とか解決に向けてということで、随分協議を進めてきました。こうした地域の力も、非常に学校としては助かりますので、今後もお願いをしていきたいというふうに考えております。"},{"i":190,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":191,"speaker":"ゆきた委員","text":"私から、この教育委員会の対応策として、区としても、どうすれば今後いじめがなくなるかというところを対策として方針として、制度的なものとしては数多く挙げていただいているところだと思いますが、焦点を実際に被害のあった方に対して、この、被害のあった当該生徒に対してどこまでケアができたのかといったところを焦点にして考えていただきたいなというふうに思います。\n実際このいじめがあった当該生徒は、他区へ転出後も、校長に対して、令和２年の１０月９日と令和３年の７月４日に、当時のいじめが解消せず苦しんでいるという内容が、校長宛てに送られてきているということで、現在も苦しんでいるかもしれない内容でございます。\nまた、他区へ転出した後も、この被害があった生徒、苦しんでいるこの生徒に対して、その後に精神的ケアとか、身体的ケアをどのようにされてきたのか、もし、その経緯というものがあるようであれば、教えていただきたいと思います。\nまた、今後、この令和２年の事案が解決とは言えないですけども、終わったと、一旦節目を終えて、品川区として、この傷があった、精神的にダメージのあった、この被害があった生徒に対して、今後他区に行ったから終わりではなくて、この生徒に対して今後どういうふうに対応を取っていただくのかといったところも、お考えがあればご回答いただきたいと思います。"},{"i":192,"speaker":"丸谷教育総合支援センター長","text":"この、今回被害に遭われた生徒へのケアについてですけれども、十分なケアができなかったということで、他区への転出をせざるを得ないという状況をつくってしまったというふうに考えております。そういった意味では、こちら学校・教育委員会としても大変反省すべきところでございます。\n今後どういう対応を行っていくかというところですけれども、今後、区長部局のほうにも調査委員会が立ち上がって調査が始まりますので、そういったことも踏まえながら、真摯に対応していきたいというふうに考えております。"},{"i":193,"speaker":"ゆきた委員","text":"この事案に対して、一番の問題といったところが、期日が空き過ぎているというところが問題だと思います。今後対応取るというような回答いただいていますけれども、真摯に対応していただくということはもちろんスピードだと感じていますので、こういった対応についてもスピードを持って対応していただきたいと思います。"},{"i":194,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":195,"speaker":"高橋（し）委員","text":"被害に遭った生徒さんとそのご家族は本当に痛ましい状況ですので、今、本当に二度とないようにということで、強く思いはあります。その中で、教育委員会としての今後の対応が出ていまして、今、各委員の方がおっしゃったようにかなり課題がたくさんあるということで、いじめは絶対許さないという状況を現場の学校の先生方そして教育委員会も粘り強く指導して、本当に二度と起きないような体制づくりをしていただきたいと思います。\n一方で、体制、組織的対応というところでどうだったのかということも、いじめ対策委員会のほうで出ていますが、冒頭、おわびをしていただいたのですが、区民の方へも含めてのおわびだと思うのですけれども、区長への、区長部局への報告についてなのですが、そこは、いじめ防止対策推進法に基づき重大事態に当たるということをそもそも念頭になかったのか。\nそれからもう一つは、いじめ防止対策推進条例第２１条の中で、区長部局に報告するという文言もあるわけですから、そのこと自体が念頭になかったのか、あるいはそれがあるけど、何らかの事情で報告が、重大事態という認定が遅れたのか、また、もう一つ、報告が遅れたのか、ちょっとそこの理由が、ご説明をいただいてないので、その点はいかがですか。"},{"i":196,"speaker":"丸谷教育総合支援センター長","text":"区長部局への報告の不備でございますけれども、区長への報告が必要ということは認識しておりまして、念頭にございました。事務手続が漏れていたということで、文書での報告ができていなかったということでございます。"},{"i":197,"speaker":"高橋（し）委員","text":"それで、いじめ対策委員会への諮問の日付が、ホームページでは５月２４日とあり、それでいじめ対策委員会の調査報告では４月１３日とあるのです。それで、いじめ対策委員会の報告によると、公文書が４月１３日付の何号というふうにあるので、ここで正式に示されたと私は思うのですが、ホームページとそのいじめ対策委員会の不備があるということ自体から何か、いわゆるコンプライアンスというか、そこについてちょっと、現在もホームページに載っています、そういうのがあって、そういうところから、私さっき、第２１条のことを認識しているとおっしゃったのですけど、そういうことも失念していたのではないかというふうなところまで、残念なような気がしたのですが、文書的なものは行かなかったということで答弁があったので、一つ確認は、７月１３日に教育長からいじめ対策委員会に諮問したということを確認させてください。それが１つ。\nもう一つは、諮問をした段階で、なぜ区長部局に伝わらないのかということです。教育委員会の中で、何の学校とかいじめ事件についてということで協議や報告があるのですけど、そこで、事務局の方々もいらっしゃるのに、どうして区長部局に話が行かなかったと、非常に不思議なのです。そこは、学校の現場の先生が、こういう事件がありました、教育委員会に報告しました、それを区長部局にも言ってくださいねと、学校から言わなければいけないのですか。相談でいいではないですか。そうすると教育委員会のほうで区長部局と連携を取るためにもしなければいけないのだと思うのですけど、その点はいかがでしょうか。"},{"i":198,"speaker":"丸谷教育総合支援センター長","text":"まず、教育長から品川区いじめ対策委員会の諮問の日付ですけれども、令和４年７月１３日ということで間違いはございません。ホームページにございます日付のほうは、確認をさせていただきまして、必要があれば修正させていただきます。\nそれから、区長への報告がなぜ漏れたかというところですけれども、文書の手続が、書面が行ってなかったということでございまして、大変ご迷惑をおかけしたということでございます。"},{"i":199,"speaker":"高橋（し）委員","text":"すみません、しつこくて。今年の令和５年の３月２９日に総合教育会議も開かれていまして、そこで、教育委員会と区長部局、区長とお話しているわけです。その中の議題にないのです。というところも、非常に、両者が密接に語っていくというところがないので、そこでも報告はなかったのですか。これちょっと、総合教育会議の所管が違うからお答えできないのかもしれませんけども、お答えできる範囲で。"},{"i":200,"speaker":"宮尾庶務課長","text":"総合教育会議、令和４年度は１回、ちょっと日にちまでは思い出せませんが３月に、区長部局と実施をしております。そのときに、特にこの議題に限ってというか、いじめに関する議題というのはありませんでした。主に、品川区の大きな教育の方向性ですとか考え方、こういったことを意見交換等したというところでございます。"},{"i":201,"speaker":"高橋（し）委員","text":"ちょっと、いろいろお話ししたのですけど、今後も含めて、教育委員会と区長部局の連携をしっかりするということで、組織体制云々ということも今後のことを書いてあったので、ぜひその辺はしっかりとお願いしたいと思います。\nもう一つ最後なのですけど、いじめ対策委員会で報告が出ました。令和５年３月２９日です。そこで、教育委員会としては、ここにあるように、大きな問題で、いろいろな課題をいじめ対策委員会のほうから提案されたわけです。\nなぜそのときに、教育委員会として説明や開催をその時点でなされなかったのかというところが、私は非常に疑問があります。その後、５月になって、区長と一緒に記者会見を開いたわけですけど、そこの経緯をちょっとご説明いただきたいと思います。"},{"i":202,"speaker":"丸谷教育総合支援センター長","text":"品川区いじめ対策委員会からの結果報告が３月２９日にございました。同日に行われました教育委員会の中で、この報告というのを差し上げたところでございます。その後、区長への報告という段階になりまして、定例記者会見が５月にあるので、そこで併せて報告しようという流れでございまして、教育委員会独自に開催するというような、その時点では考えはございませんでした。"},{"i":203,"speaker":"高橋（し）委員","text":"いや、区長と一緒に記者会見をしたときに、こういう経緯があってこうこうだとご説明されたことは、その中身がどうとかと言うつもりは全くありません。そうではなくて、３月２９日に答申をもらって、教育委員会でも区長へ報告したわけですよね。その段階で、教育委員会としてはこうだった、教育委員会だけでどうして記者会見をしないで、区長と一緒に記者会見をする必要があったのかということを聞きたいのです。\n教育委員会がこうやってきちっと対策も、いろいろ課題はありましたけどいじめ対策委員会も開き、こういう問題があって指摘を受け、今後も、冒頭おわびされていたようにしっかりやっていくというお話しているわけですから、私はそのこと自体は何ら責めるつもりはないです。それをどうして教育委員会だけでやらなかったというのを、ずっと僕思っていたのです。それで、報告するといったら区長が今度記者会見やります。その中の一部で説明されているわけです。私は教育委員会としてきちっと対応を考えてしっかりこれからやろうという思いを受けています。それをその時点でしなかったということがどうしても納得いかないのです。すみません、もう１回お願いします。"},{"i":204,"speaker":"米田教育次長","text":"この間、様々いじめ対策委員会のほうで調査をしていただいて、答申が３月の２９日にいただいたわけでございます。その件を含めまして、きちんとその中身を区長にも伝えなければならないし、議会のほうにも伝えなければならないというふうに思っていたところではございますが、まず、そちらのほうを優先をさせよう、それから調査結果報告については、当事者の方に内容を確認するというような必要もありますので、まず、そちらのほうを優先させて、区長の報告は、それからまた、文書での報告についてはしばらく後になったというようなことでございます。その時点におきまして、教育委員会といたしましては、報告をまず、きちんとしようというようなところがございましたので、正直なところ記者会見というところの認識までにはその当時は至っていなかったというようなものでございます。"},{"i":205,"speaker":"高橋（し）委員","text":"そういうとまた、何かずっと聞きたくなってしまって申し訳ないのですけど、その時点で、いろいろな事務、３月２９日に発表し直してくださいとは言っていません。教育委員会は独立して教育行政をしっかりやっていただいているわけです。その独立性というのはものすごく重要で、その独立性を持ったという立場で、私は責任を感じ、今後こういうふうにしていくということをお話ししてきていただきたかったというふうに、僕は言っているのです。\nだから、その独立性を持たなければいけないのに逆に、区長部局への報告が遅れるという、変な独立性とは言っていないのですけど、そこのところはそれを言ってはしようがないのですけど、ぜひ、教育委員会としての独立性を持った、そういう、特に発表のところ、聞いてもお答えいただけないのでしょうけど、教育委員会だけで発表をしないというふうに決めたのはなぜですか。そこは最後お聞きします。"},{"i":206,"speaker":"米田教育次長","text":"お答えになっているかどうかあれですけれども、教育委員会といたしましては、きちんとこの問題について対処をしていこうということについては認識はしていたところでございますが、先ほど申し上げましたように、まずは、様々な関係者に対してのご説明を先にということで、ご指摘が、記者会見をしなかったということでのご批判と受け止めておりますが、そちらについては、認識として、そこまでに至ってなかったということで、その辺のところが認識が甘いというようなご指摘、そのほかのご指摘も多々あろうかと思いますが、そちらは真摯に受け止めて、今後教育委員会としての対応等に生かしてまいれればと思う所存でございます。"},{"i":207,"speaker":"高橋（し）委員","text":"すみません、長くなりました。記者会見を教育委員会としてやらなかったかという話ではなくて、記者会見ではなくても発表の方法はあったので、教育委員会として、ぜひ、区長と一緒ではなくて、していただきたい教育委員会としての矜持というか、それを示していただきたかったと思って、すみません、長くなりました。"},{"i":208,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":209,"speaker":"吉田副委員長","text":"今まで皆さんの議論で、本当にいろいろ意見交換ができてよかったと思います。私からは、すごく初歩的というか、そもそもの話になってしまうかもしれないのですけども、この事件について、いじめを認定するに当たっては、被害生徒の訴えの後、直ちにこれをいじめと認定しているというところで、いじめの認定はとても素早かったなというふうに思います。それで、いじめの認定というのは、訴えがあれば、基本的にはもういじめはあったとして認定されたという理解でよろしいでしょうかという確認が１つ。\nそれから、それが遅れたのが、この事例が重大事態に当たるというところで、その判断が１個遅れているかなと思います。それで、いじめの重大事態という判断はどこでどういうふうにするのでしょうか、ということを伺いたいと思います。\nそれで、もう一つ調査としては、先ほどアンケートも、というふうにおっしゃっていたと思うのですけども、家庭に持ち帰って保護者の訴えも含めたようなアンケートの取り方というのは、具体的にどのような方法を取られているのか、誰の目も気にせずに、実はうちの子がいじめられているとか、実は自分はいじめに遭っているとかいうことが答えられるようなアンケートになっているのか、その辺についても伺いたいと思います。\n先ほどは、いじめは素早く認定されているので、現在、その重大事案に当たらないけれども把握しているような数が、教育委員会事務局としても把握されているようであれば、教えていただきたいと思いますが、いかがでしょうか。"},{"i":210,"speaker":"丸谷教育総合支援センター長","text":"いじめの認知や、いじめの重大事態の認知、認定については、学校の中にある組織である、学校いじめ対策委員会で行うことになっております。いじめの認知については、法令に定められている要件を満たしているかどうかを学校いじめ対策委員会で判断をして、いじめ、もしくはいじめてないというような判断をしております。\n重大事態についても、この法令に基づいて、判断をその学校いじめ対策委員会、もしくは、こちらの設置者のほうで判断するということになっています。\nまた、アンケートの内容についてですけれども、今回のいじめの重大事態については、当然いじめがあったときに、誰がやったかが分からなかったわけですから、アンケートを取って、見たか、聞いたか、知っているか、というような内容のアンケートは取ってございます。それでもなお、分からなかったという事案でございます。\nそのほか一般的には、学校には目安箱というものを用意していまして、自分がいじめられているですとか、いじめに遭っている子を知っているですとか、そういったものは常日頃から投函できる仕組みというのは整えております。中学校には目安箱とアイシグナルというものも用意してございます。"},{"i":211,"speaker":"吉田副委員長","text":"今のご答弁の中には、では今、いじめとは認定しているけど重大事態には至っていないというようなものの把握について言及がなかったのですけど、その辺についていかがでしょうか。"},{"i":212,"speaker":"丸谷教育総合支援センター長","text":"失礼いたしました。いじめの認知は毎月学校から報告を上げていただいていますので、数としては把握をしています。その中で重大事態に当たるか当たらないかの判断については、このいじめ防止対策推進法の２８条に照らして判断していくわけですけれども、今回、令和５年５月にそういった事案が発生しましたので、報告をしてこの後、調査報告に当たるという事例が１件あるということでございます。"},{"i":213,"speaker":"吉田副委員長","text":"分かりました。では、結局重大事態かどうかも、学校の中でまず、判断があって上がってくるということでよろしいのですね、というのと、それから、そのいじめというものだけれども重大事態まで至らないというものについての、いじめと認定した段階でのその後の対応のやり方というのも、やはりこの学校のいじめ対策委員会の中で共有されて、教育委員会事務局にも報告が上がってくるという理解でよろしいでしょうか。"},{"i":214,"speaker":"丸谷教育総合支援センター長","text":"まずは学校での判断ということになりますが、学校から上がってくる報告を教育委員会で点検をしながら、これは重大事態に当たるおそれがある、疑いがあるというところでの、こちらの把握しながら学校と、校長とセンター長で話をしながらという仕組みを今つくっているところでございます。"},{"i":215,"speaker":"吉田副委員長","text":"分かりました。ありがとうございます。それで、今回の場合は、加害生徒が判明しなかったというところで、それが難しいとは思いますけれど、ほかの方からもご意見出ましたが、やはり加害生徒へのカウンセリングという視点も非常に大事だと思います。家庭だけの問題ではなくて、本人も何かそういうものを抱えている可能性があるので、加害生徒への対応というのも非常に大事かなというふうに思っていますので、その辺もぜひ今後は検討していただきたいと思います。\nそれから、やはり、学校の中での対応はもう当然必要なのですけど、子どもがこういうことに遭ったときに、第三者的な立場で、子どもに寄り添ってくれるような相談機関というのはやはりどうしても、ここまで来ると必要なのではないかなというふうに思います。これまでも、このいじめに限らず、やはり、子どもが安心して自分の立場に立って相手は聞いてくれるというような第三者的な機関というものの設置を求めてまいりました。やはり、こういう事態が起きると、ぜひ品川区教育委員会として、区長部局と連携しながら、どこの所管になるかは分かりませんけれど、そういう機関の設置というのをぜひ検討していただきたいと思います。\nそれから、やはり、究極のところ言ったら、警察との協力というのは素早くやっているわけです。すぐに警察にということなのですが、警察でやったのは結局いじめ行為の停止という感じで、教育的視点は警察に求めるのは難しい。やはり、その辺は教育委員会として、学校と連携してやっていっていただきたいのと、それから、防犯カメラも、どうしてもとなったらそういうものに頼らざるを得ないのかなというふうに思いますけれど、そういうことを、監視の目を強めれば死角をみんなは探すと思うのです。絶対防犯カメラは設置されないであろうトイレを心配いたします。これまでもいじめの事例とか聞くと、トイレの中で、本当に、ちょっと口に出すのもはばかられるようないじめが行われたということも聞いておりますので、その辺は、必ず監視の目を強めれば死角を必ず探すという心理も働くと思いますので、その辺はぜひご配慮いただきたいというふうに思います。\n今後に向けてはやはり、被害生徒とともに加害生徒へのカウンセリングというのを視野に入れた対応をしていただきたいと思います。"},{"i":216,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":217,"speaker":"高橋（し）委員","text":"先ほどちょっと、最後聞き忘れたのですけれど、いじめ防止対策推進条例２１条で、重大事態が発生した旨を区長に報告しなければいけないというのですが、その区長部局の窓口はどこの所管になるのかということが１つ。\nそれから、先ほどセンター長が、認識はしていたが文書での報告を怠ったというお話だったのですが、ということは、口頭での報告をどの時点でお話しされていたのかということをお尋ねします。すみません、先ほど聞き忘れて、申し訳ありません。"},{"i":218,"speaker":"丸谷教育総合支援センター長","text":"区長部局への報告の窓口となるのは総務課でございます。今回新たな事案も総務課に書面で報告を上げております。\nまた、当時文書報告を怠った、失念していたということでございまして、口頭でというところにつきましては記録が残っておりませんので、控えさせていただきたいと思います。"},{"i":219,"speaker":"高橋（し）委員","text":"総務課のほうが、今回も、次の調査委員会のほうの所管にもなっているので、そこと協力体制というのをしっかりとつくっていって、先ほどの、今後のということをやっていかなければいけないのですが、文書での報告は失念していました、口頭での報告は記録が残っていないので分からないというご答弁と確認させていただいてよろしいですか。"},{"i":220,"speaker":"丸谷教育総合支援センター長","text":"そのとおりでございます。"},{"i":221,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nなければ、では私から。改めて、そもそもいじめというのはどういうことか教えてください。"},{"i":222,"speaker":"丸谷教育総合支援センター長","text":"いじめの定義でございますけれども、いじめ防止対策推進法の第２条に記載がございます。「「いじめ」とは、児童等に対して、当該児童等が在籍する学校に在籍している等当該児童等と一定の人的関係にある他の児童等が行う心理的又は物理的な影響を与える行為（インターネットを通じて行われるものを含む。）であって、当該行為の対象となった児童等が心身の苦痛を感じているものをいう」というふうに定められております。"},{"i":223,"speaker":"つる委員長","text":"それがいじめです、法律上。それで、今回は、先ほど各委員からそれぞれ、非常に大事な視点もあったと思いますし、これからのことということでの具体的な提案も含めて、あったかと思います。今回のことは、いろいろそのタイミングは別にしても、そもそもスタートラインが、いわゆるいじめを受けたということを受けて、相談があったところを起因として初動が始まったというところです。それは、いわゆる被害を受けている、この場合は生徒が、報告、相談をしてスタートしているわけです。法律上も、今先ほどご説明いただいたのは、関係性でいくと、被害を受けている生徒ないし児童、そして、危害を加えている、いわゆる加害をしている児童・生徒というのがあって、法律上はいじめというふうになっているという理解なのですが、そこの認識がちょっと合っているかどうか教えてください。"},{"i":224,"speaker":"丸谷教育総合支援センター長","text":"被害に遭った生徒も、加害を行った生徒も、同じ、一定の関係がある者同士というふうに定められております。"},{"i":225,"speaker":"つる委員長","text":"今回のケースは、被害を受けていらっしゃった、もう他校に行ってしまった生徒の方からの相談です。ですが、いわゆる加害を行った、この資料とか、調査結果の表記でいくと、何者か、それが特定できないという中にあって、いわゆるいじめと。それで、ただその事態が発生しているのは、エンクローズされた学校の中という、もっと言えば教室の中というところの中で、先ほど来の質疑聞いていると、初動の段階でも警察の方も一定程度協力をいただいている。なので、法律に基づく２８条とか２１条と先ほど来、条文というか、出てくる中で、その何者かを特定できていない。だけれども、今回、先ほどその調査結果の報告ですとか、記者会見の話とかもありましたけれども、それはある意味、事後的なことかなと思う中で、先ほどどなたかもおっしゃっていましたが、その被害を受けている方の幸福というか、そのために全力を傾けていくというのが、やはり教育委員会ないし学校現場の役割だということを考えたときに、その子がどう今なっているかというのは、やはり、それは職責上、責任がある、ないとかまた出てくるのかもしれませんが、非常にその子の将来をどうするかというのは、その思いというのは、やはり矜持として教職員が持っているものという前提認識で、私も今年４８になりますけど、生きてきて、思っているのです。\nこの中にある中で、その被害を受けられた方には、特定してほしいという思いがある。だから今回、区長部局にもそうしたところの、教育委員会の対応も含めた、学校現場での対応も含めたところも含んで、いろいろそういう、いわゆる調査が進んでいくのだと。先ほど安藤委員から質疑していただいたかと思うのですけど、今回はその何者かであるわけですし、先ほど石田しんご委員もおっしゃっていた、体育館に集められて校長から切々と話をされても、それは響かないというような、なかなか解決に至るというのは難しいですよという、経験則もあるのでしょうけど、そうですか。\nこれはなかなか難しいと思うのです。そういう中では、今回のこの上がっている報告事項の中の方に限って言うのです。やはり、そこに求められていることに対して、区としてどう応えていくかということが、このお一人の将来というのをどう対応していくか。責任がある、ないとかはまたこれ別です。どうやっていくかというのがその一人の人生に大きく関わっていると思うのです。だからこそ、区長部局でもそういうのを設けられたのだと思うのです。なので、先ほどから各委員からあったいろいろな指摘、また、提案等をしっかりと酌んでいただいて、やはり、本当に、「二度と」という言葉というのは何度も使われるわけです。「二度と」というのは便利な言葉だなと思うのです。やはり、そういう現実に対してどう対応いただくかというところの部分を常にお互いが構築していかないと、この課題というのは解決できないと思うのです。\nだから、各委員から今日あったことはしっかりとぜひ、真摯に受け止めて、やはり風通しのいい場にしていかなければいけないと思うのです。やはり今、いろいろなことが発達していますから、子どもたちの受け止めというのは早いです。反応も早いのです。ああいう視点もしっかりと認識していただく必要もあるのかなと。\nこれ、私、当時、先ほど出た２０１２年のとき、決算特別委員会のときにも引用させていただいたのですけど、私自身の経験を通してということで。その当時の中学校のときの担任が、卒業アルバムに「将来は政治家か、または社会科の教師を目指し頑張ってくれたまえ、政治家になったときは私の再就職を頼む」とアルバムに書いていただいて、政治家という言葉嫌いなのですけど、今、こういう職責をいただいて。私的な話ですけど、過日の選挙のときに、初日に偶然、武蔵小山の駅頭で立っていたら、共通の中学校の教え子が有名な料理人で、私、先輩ですけど、その方に会うために来ていて、ちょうど私がお話をするときに話を聞いてくれたのです。まるで逆授業参観というか、そういうシチュエーション。それで伺ったら、今ちょうどたまたま、品川区内の学校で講師として教えていると。この夏でちょうどもう引退考えているのだと。「なかなかよかったよ、抑揚があっていいね、聞きやすかった」。そういう教師もいるのです。卒業した後も。\nこれも余談ですけど、何年目かの議員させていただいて、新宿にＩＣＴの視察に行った。たまたま偶然そこにいた先生が、その先生だった。「何やってるんだ、お前」という。会った瞬間に「当時お前こうだったな」と。その担任の先生とか、学年の先生が、当時こんな体制ないですよ、３４年前。全力で命がけで守ってくれた。だから、２０１２年の決算特別委員会のときに私言っていますけど、だからここでこうやって、当時の課題についても、その方の代弁者になれるかどうか分からないけども、二度とそういうことがないように、区民の代表の立ち位置で質疑もさせていただいた。だけど、先ほど安藤委員もおっしゃっていた、学校は社会の縮図だから、なくならないのです。そういうご認識でお答えもいただいている。\nだから、制度とか、システムとか、仕組みとか、対応、体制、プログラムとか、そういう次元ではない。それも大事。だけれど、やはり今回報告いただいたことだけを受けると、やはり現場の教職員の方が、本当にその児童・生徒と、私を育てていただいたその中学校の教師のように、子どもたちの将来を、たくさんの先生方がそうだと思う、だけども、一方でいろいろな複雑化している社会の縮図の中で、そういうしんどい思いをしている人がいるというところを、やはり、どこまでも突き詰めていかなければ、このことというのは解決に至らないし、やはり、先進行く品川区として、今後やはりやっていくに際しては、そこをもう一歩、一重、二重、皮をむいてやっていただきたいなと。\nやはり、このいじめの関わりが出ると、私はどうしても、今日は委員長ですけど、やはりお伝えしたい。各委員も今日は全員が発言をされる、そういう課題だと思うのです。でも、どこまでいってもシステムの話ではなくて、一人の生身の人間の話なのです。しんどい思いをしている目の前の人の話なのです。これはもう絶対、理事者の皆様も当たり前のごとく認識をしていただいている。我が子だったら、我が事だったらと。さんざんＳＤＧｓがさとかと言うけれども、その認識を、やはり今後もどう深めていけるのかな。報告書を読むとちょっと切なくなってくるような対応がいっぱいありますでしょう。しんどかったんだろうなあと。僕がその場にいれたらよかったなと。どういうふうにして味方になれたかなと。\nなおかつ特定ができていない。疑われてしまっている可能性だってある。そういう、そこまで、やはり突き詰めて見ていかなければ、閉ざされた中で子どもたちがいろいろな考えの中で、尺度で大人を見ていると思うのです。子ども同士のことだけでの課題ということで囲うのではなくて、そういう視点もやはり、今度、区長部局で設けられたところでの進展についてはあるのかなと期待しますけれども。そうしたところも含めて、ぜひ、今回、報告が上がっている生徒が、本当に希望を持って、すっきりできるように、品川区の姿勢を示すしかないです。前に向かっていくしかないのです。だからそれをぜひ、こうした委員会の、また議会側も、区民の代表です。通して各区民に伝わります。各議員も聞きます、聞かれます。だから、そういったことも含めて、ぜひ、この課題については、あえて委員長ですが、お時間いただいて、発言をさせていただきましたので、ぜひ、最後申し上げましたけども、各委員の提案も含めて、ぜひ酌んでいただいて、具体的なまた、今後の報告の期日も示されておりますので、それに限らず、風通しのいい教育委員会になるようにしていただきたいなと。それこそ二度とこうしたことが報告事項等にならないような品川区にぜひしていきたいと、私も文教委員長としてそう決意しています。ぜひよろしくお願いします。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(9) 令和５年４月入園申請状況等について"},{"i":226,"speaker":"つる委員長","text":"次に、(9)令和５年４月入園申請状況等についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":227,"speaker":"立木保育課長","text":"それでは、私からは、令和５年４月の入園申請状況等についてご報告いたします。資料をご覧ください。\n１の保育提供区域別申請状況の表に、子ども・子育て支援事業計画で定めております保育提供区域別に、年齢ごとの申請者数、入園者数、不承諾数、待機児童数を記載してございます。\n表の下のほう、２の全体数の表をご覧ください。全体で、申込者が３,１２５人で、前年から３６人の減となりました。入園者数は２,４１１人で前年から１５６人の増。不承諾者数は７１４人で、前年から１９５人の減となりました。待機児童は、令和４年度に引き続き０となってございます。\n次に、２ページ目、裏面をご覧ください。参考といたしまして、令和５年５月の地区別、年齢別の入園可能数を、１ページ目の入園状況と対比できる形で記載してございます。年齢別では０歳児が３３６人、１歳児が１３６人、２歳児が２１３人、３歳児が１７３人、４歳児が３２０人、５歳児が４６５人、合わせまして全体で１,６４３人の空きがございました。"},{"i":228,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":229,"speaker":"安藤委員","text":"これは待機児が数字は０ということなのですが、不承諾の方はやはり７００人以上いらっしゃるということなのですけど、ちょっと幾つか教えてもらいたいのが、不承諾の内訳です。これちょっと、毎年、厚労省からも報告をしているので、ちょっと、そういった数字を出していると思うのです。それで聞きたいのですが、例えば、求職活動、求職というのは求めるほうです、この活動を休止している者ということで、保育園に入れないがために求職活動を休止した方は何名だったのか。それと特定の保育園等のみ希望している者という方は何人だったのか。あと、育児休業を延ばした方は何人だったのか。それと、地方単独事業を利用している方という中で、いわゆる区立の定期利用保育事業という、空きスペースを使って何年か限定で１年間入れる、ということの利用者は何人か。あとは、認可外保育園、助成は受けているけど、認可外保育園に入っているから待機児とはみなされない方、何人なのかというのを伺いたいというのが１つ。\nもう一つは、地域別にこの申請状況等出ておりますが、不承諾で言うとやはり品川地区と東大井・八潮地区が多めに見えます。五反田地区も多いほうですか。逆に少ないのが大崎地区と荏原地区ということなのですけど、この多い所と少ない所はなぜこういうふうになっているのかというのを教えてください。"},{"i":230,"speaker":"石井保育支援課長","text":"まず、不承諾者数の内訳についてご質問でございます。先ほど委員からご質問ございました、求職活動を休止している者でございますが、こちらは１７名でございます。\n続きまして、特定の保育園等のみ希望している者でございますが、こちら１園のみの希望者ということで８７名ございます。\n続きまして、育児休業中の者につきまして、こちら１９３名でございます。\n地方単独事業の中で、定期利用保育事業の利用者につきましては、８名でございます。\n続きまして、認可外保育園を利用されている方で、助成制度を受けている方ですけれども、こちらは３名でございます。\n続いての、保育提供区域別申請状況で、多い所と少ない所、それぞれありますけれども、不承諾者数の多い少ないということは申請者数の増減とかもございますので、そういったところが影響しているところではないのかなというふうに考えてございます。"},{"i":231,"speaker":"安藤委員","text":"不承諾の中を見ると、やはりその様々、これも待機児童ではないのかなという方が含まれているということだと思います。なので、待機児０になったからといって、年度途中の入園というのはなかなか絶望的な状況は変わらないですし、あと、非正規の方もなかなか入りづらいということですとか、様々あると思います。なので、そこも見据えて、やはり保育園の整備というのはしていく必要があるというふうに私は思います。\n最後２点、お伺いして終わりにしますけど、ちょっとごめんなさい、特定の保育園等のみ希望している者で、全体というのですか、特定の保育園のみ希望している者という定義の中で全体の数は何人ですかということと、それと、来年、新年度に新たに、あるいは今年度途中でもいいのですけども、今年度途中あるいは来年の４月に新規増設する認可保育園の園数と定員数というのは、もし今分かっているのがあれば教えてください。"},{"i":232,"speaker":"石井保育支援課長","text":"先ほどご質問ございました、特定の保育園のみの希望している者でございます。先ほど１園のみ希望者８７名と申しましたが、それ以外の要因が１１４名ございますので、合計で２０１名となってございます。\n続きまして、今年度の新規開設予定園でございますけれども、現在相談を受けているところでございまして、決まりましたら改めて、この文教委員会の場でご報告をさせていただきたいと思っております。"},{"i":233,"speaker":"つる委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で本件および報告事項を終了いたします。\n────────────────────────────────────────────\n４ その他"},{"i":234,"speaker":"つる委員長","text":"委員会時間が１７時１５分を過ぎておりますので、ご了承いただければと思います。\n最後に、予定表４のその他を議題に供します。\nその他で何かございますでしょうか。"},{"i":235,"speaker":"石井保育支援課長","text":"私から、その他ということで、１園、区内における小規模保育事業の廃止についてご報告させていただきます。\nまちの保育園えばらという、荏原地区にございます小規模保育事業、こちら定員１２名のところでございますけれども、令和５年度いっぱいの運営でもちまして、閉園となってございます。\nこちら、平成２７年の６月より、品川区で小規模保育事業を行っていたのですけれども、その後、品川区が行ってきた待機児童対策により、近隣に認可保育園が建ってきたというふうなこともございまして、園児数が減少しており、そういったことからも、今後園児数の減少は続くものであろうということの法人判断がございまして、このたび閉園に至ったものでございます。"},{"i":236,"speaker":"つる委員長","text":"報告が終わりました。本件について、特にご確認等はございますでしょうか。"},{"i":237,"speaker":"安藤委員","text":"今入っている方の対応というのでしょうか、そこをどのようになされているのか、行き先がなくて困ってしまうとか、そういうことはないのか、伺いたいと思います。"},{"i":238,"speaker":"石井保育支援課長","text":"在園児に対してのことでございますけれども、まず、２歳児に関しましては、連携施設への進級を行うことができます。一方で、１歳児クラス、０歳児クラスにつきましては、転園の手続をこれから進めてまいるのですけれども、指数の２点加点ですとか、あとは、こちらのほうでもきめ細かな相談に乗りながら、行き先がなくならないよう努めてまいりたいと思っております。"},{"i":239,"speaker":"安藤委員","text":"ぜひ、行き先がなく困らないように、ぜひ対応、相談など精いっぱいやっていただきたいと思います。"},{"i":240,"speaker":"つる委員長","text":"ほかにございますか。\nないようですので、本件を終了いたします。\n正副委員長より２点ご案内申し上げます。\nまずは、所管事務調査についてです。５月２９日の委員長会および正副委員長会において、議長より、これまでと同様に、所管事務調査に積極的に取り組んでほしい旨の発言がありました。当委員会としましても、委員会の活性化の観点から、積極的に取り組んでいく必要があると考えております。\nつきましては、年間を通して協議したい課題や調査事項等につきまして、委員の皆様からご発言をいただき、委員会日程等を考慮しながら、できる限り調査していきたいと考えております。\nご参考までに過去の調査項目について、委員の皆様にはお配りをしております。\nそれでは、所管事務調査について、何かこの場でご意見等がございましたら、ご発言願います。"},{"i":241,"speaker":"安藤委員","text":"児童相談所の件で、来年いよいよ１０月に開設なので、やはりちょっとしっかり調査していく必要があるかなというふうに思います。\nそれと、あと、不登校の対策というか支援といいますか、ちょっとやはり、いじめと並んで、今の学校の一つの子どものつらさの反映かなと思っていますので、そういったところも調査できたらなというふうに希望したいと思います。"},{"i":242,"speaker":"つる委員長","text":"ほかにございますか。\nそれでは、ただいまいただきましたご意見を含め、ほかに調査したいテーマがございましたら、６月１９日月曜までに事務局へご提出いただきたいと思います。\n日程的なこともございますので、提出されましたそれぞれのテーマにつきましては、資料等の準備などを含め、調査可能かどうか、理事者と協議をさせていただきまして、次回の委員会で正副委員長案をご提示し、改めまして、所管事務調査の調査項目として決定してまいりたいと思います。よろしくお願いをいたします。\n次に、行政視察についてです。\n今年度の行政視察の調査事項、視察先、日程等につきまして検討していきたいと考えております。参考資料として、過去の視察先と調査項目についてまとめたものをお配りしております。\n本日のところは持ち帰りとしますが、あらかじめ、先ほどの所管事務調査についてと同様に、行政視察において調査したい項目や、行き先等についてご意見があれば伺いたいと思います。\nそれでは、行政視察の調査項目や行き先等について、何かこの場でご意見等がございましたら、ご発言願います。"},{"i":243,"speaker":"安藤委員","text":"先ほどもちょっと、コロナの学級閉鎖の話ありましたけど、東京でも増えて、４週連続で定点観測が増えていますし、全国的にも同様なので、ちょっと感染状況を見て、その日程ですとか、あるいは開催の有無も含めて、機敏に正副委員長には柔軟に対応していただきたいと、今から増えた場合の中止の検討も含めて、その辺についてはお願いしたいと思っております。"},{"i":244,"speaker":"つる委員長","text":"ほかにございますか。\nただいまいただきましたご意見を含め、ほかに調査したい項目や行き先等がございましたら、６月１９日月曜までに事務局へご提出いただきたいと思います。\n以上で、その他を終了いたします。\n以上で、本日の予定は全て終了いたしました。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ５時２６分閉会"}]});
